{
  "name": "Bangla SEO AI Writer Pro",
  "description": "An advanced AI-powered platform for generating high-quality, SEO-optimized Bangla articles and automatically publishing or scheduling them to WordPress."
}

export interface WPSettings {
  url: string;
  username: string;
  appPassword: string;
}

export interface GenerationParams {
  topic: string;
  primaryKeyword: string;
  secondaryKeywords: string;
  targetAudience: string;
}

export interface GeneratedArticle {
  title: string;
  slug: string;
  content: string;
  metaTitle: string;
  metaDescription: string;
  tags: string[];
  featuredImagePrompt: string;
}

export interface WPPostResponse {
  link: string;
  id: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are an expert Bangla SEO content writer and Google AdSense specialist. 
    Your goal is to write a human-like, conversational, and authoritative article in Bangla.

    CRITICAL RULES:
    1. Language: Natural, clean, and professional Bangla. No robotic or obvious AI tone.
    2. Length: Minimum 1000-1200 words. Be exhaustive and detailed.
    3. Structure:
       - H1 Title: Must include Primary Keyword.
       - Intro: 150-200 words, include PK once.
       - Body: Use UPPERCASE H2 headings. Each H2 must have H3 subheadings.
       - Paragraphs: Short (2-3 sentences).
       - Lists: Use <ul> and <ol> with <li>.
       - Table: Include at least one informative HTML table.
       - FAQ: 4-5 'People Also Ask' style questions.
       - Conclusion: 100-150 words with a strong CTA.
    4. SEO Elements:
       - Meta Title (with PK).
       - Meta Description (150-160 chars).
       - URL Slug: English translation of the Primary Keyword (lowercase, hyphenated).
       - Tags: 10-15 relevant tags (Bangla & English).
       - Featured Image Prompt: Realistic blog thumbnail description in English.
    5. HTML Formatting: Return only valid HTML for the 'content' field that can be directly used in WordPress.
  `;

  const prompt = `
    Topic: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Audience: ${params.targetAudience}

    Please write a comprehensive, high-quality, SEO-optimized article based on the instructions.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          slug: { type: Type.STRING },
          content: { type: Type.STRING },
          metaTitle: { type: Type.STRING },
          metaDescription: { type: Type.STRING },
          tags: { type: Type.ARRAY, items: { type: Type.STRING } },
          featuredImagePrompt: { type: Type.STRING }
        },
        required: ["title", "slug", "content", "metaTitle", "metaDescription", "tags", "featuredImagePrompt"]
      }
    }
  });

  return JSON.parse(response.text);
};

import { WPSettings, WPPostResponse } from "../types";

export const publishToWP = async (
  settings: WPSettings,
  article: { title: string; content: string; slug: string; date?: string }
): Promise<WPPostResponse> => {
  const { url, username, appPassword } = settings;
  const baseUrl = url.endsWith('/') ? url.slice(0, -1) : url;
  const apiEndpoint = `${baseUrl}/wp-json/wp/v2/posts`;

  // Basic Auth Header
  const auth = btoa(`${username}:${appPassword}`);

  const body: any = {
    title: article.title,
    content: article.content,
    slug: article.slug,
    status: article.date ? 'future' : 'publish',
  };

  if (article.date) {
    // WordPress expects ISO8601 format or similar
    body.date = article.date; 
  }

  const response = await fetch(apiEndpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Basic ${auth}`
    },
    body: JSON.stringify(body)
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.message || 'WordPress publishing failed.');
  }

  const data = await response.json();
  return {
    link: data.link,
    id: data.id
  };
};

import React, { useState, useEffect } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeyword: '',
    secondaryKeywords: '',
    targetAudience: ''
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      setWpSettings(JSON.parse(saved));
    }
  }, []);

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeyword) {
      setError('দয়া করে টপিক এবং প্রাইমারি কিওয়ার্ড লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: article.content,
        slug: article.slug,
        date: isScheduling ? scheduleDate : undefined
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Navbar */}
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg text-white">
                <FileText size={24} />
              </div>
              <h1 className="text-xl font-bold text-gray-900 hidden sm:block">Bangla SEO AI Writer</h1>
            </div>
            <div className="flex gap-4">
              <button 
                onClick={() => setActiveTab('generate')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-medium transition-colors ${activeTab === 'generate' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:text-gray-900'}`}
              >
                <FileText size={18} /> রাইটার
              </button>
              <button 
                onClick={() => setActiveTab('settings')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-medium transition-colors ${activeTab === 'settings' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:text-gray-900'}`}
              >
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-3 text-red-700">
            <AlertCircle size={20} />
            <p>{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg flex flex-col gap-2 text-green-700">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} />
              <p className="font-semibold">সফলভাবে পোস্ট করা হয়েছে!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 underline ml-8">পোস্টটি দেখুন</a>
          </div>
