                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                <p className="text-xs text-gray-400 mt-1">Users -> Profile -> Application Passwords থেকে তৈরি করুন।</p>
              </div>
              <button 
                onClick={saveSettings}
                className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold hover:bg-blue-700 flex items-center justify-center gap-2"
              >
                <Save size={18} /> সেটিংস সেভ করুন
              </button>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Form */}
            <div className="lg:col-span-1 space-y-6">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                <h2 className="text-lg font-bold mb-4 text-gray-900 flex items-center gap-2">
                  <FileText size={20} className="text-blue-600" /> কন্টেন্ট ইনপুট
                </h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">আর্টিকেল টপিক</label>
                    <textarea 
                      rows={2}
                      value={params.topic}
                      onChange={(e) => setParams({...params, topic: e.target.value})}
                      placeholder="যেমন: এসইও ফ্রেন্ডলি কন্টেন্ট রাইটিং টিপস" 
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">প্রাইমারি কিওয়ার্ড</label>
                    <input 
                      type="text"
                      value={params.primaryKeyword}
                      onChange={(e) => setParams({...params, primaryKeyword: e.target.value})}
                      placeholder="যেমন: SEO Friendly Content" 
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">সেকেন্ডারি কিওয়ার্ডসমূহ</label>
                    <input 
