              />
              <div className="flex gap-4">
                <button 
                  onClick={() => setShowScheduleModal(false)}
                  className="flex-1 py-3 border border-gray-200 rounded-xl font-bold text-gray-600 hover:bg-gray-50"
                >
                  বাতিল করুন
                </button>
                <button 
                  disabled={!scheduleDate || publishLoading}
                  onClick={() => handlePublish(true)}
                  className="flex-1 py-3 bg-orange-500 text-white rounded-xl font-bold hover:bg-orange-600 disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {publishLoading ? <Loader2 size={18} className="animate-spin" /> : <Calendar size={18} />}
                  শিডিউল কনফার্ম
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <footer className="bg-gray-900 text-gray-400 py-12 mt-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
            <div>
              <div className="flex items-center gap-2 text-white mb-4">
                <FileText size={24} className="text-blue-500" />
                <span className="text-xl font-bold">Bangla SEO Writer AI</span>
              </div>
              <p className="max-w-md">আপনার ওয়েবসাইটের জন্য ১০০০+ শব্দের সম্পূর্ণ প্রিমিয়াম এবং এসইও অপ্টিমাইজড বাংলা আর্টিকেল তৈরি করুন নিমিষেই।</p>
            </div>
            <div className="text-right text-sm">
              <p>© ২০২৪ সয়ংক্রিয়ভাবে জেনারেট করা।</p>
              <p>পাওয়ারড বাই Gemini AI & WordPress REST API</p>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
