export interface WPSettings {
  url: string;
  username: string;
  appPassword: string;
}

export interface GenerationParams {
  topic: string;
  primaryKeyword: string;
  secondaryKeywords: string;
  targetAudience: string;
}

export interface GeneratedArticle {
  title: string;
  slug: string;
  content: string;
  metaTitle: string;
  metaDescription: string;
  tags: string[];
  featuredImagePrompt: string;
}

export interface WPCategory {
  id: number;
  name: string;
}

export interface WPPostResponse {
  link: string;
  id: number;
}

import { WPSettings, WPPostResponse, WPCategory } from "../types";

const getAuthHeader = (settings: WPSettings) => ({
  'Authorization': `Basic ${btoa(`${settings.username}:${settings.appPassword}`)}`
});

const getBaseUrl = (url: string) => url.endsWith('/') ? url.slice(0, -1) : url;

export const fetchCategories = async (settings: WPSettings): Promise<WPCategory[]> => {
  const baseUrl = getBaseUrl(settings.url);
  const response = await fetch(`${baseUrl}/wp-json/wp/v2/categories?per_page=100`, {
    headers: getAuthHeader(settings)
  });
  if (!response.ok) throw new Error('Failed to fetch categories');
  return response.json();
};

export const uploadMedia = async (settings: WPSettings, file: File): Promise<number> => {
  const baseUrl = getBaseUrl(settings.url);
  const formData = new FormData();
  formData.append('file', file);
  formData.append('title', file.name);

  const response = await fetch(`${baseUrl}/wp-json/wp/v2/media`, {
    method: 'POST',
    headers: {
      ...getAuthHeader(settings)
      // Note: Don't set Content-Type, let the browser set it with boundary
    },
    body: formData
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message || 'Media upload failed');
  }

  const data = await response.json();
  return data.id;
};

export const publishToWP = async (
  settings: WPSettings,
  article: { 
    title: string; 
    content: string; 
    slug: string; 
    date?: string; 
    category?: number;
    metaDescription: string;
    featuredMediaId?: number;
  }
): Promise<WPPostResponse> => {
  const baseUrl = getBaseUrl(settings.url);
  const apiEndpoint = `${baseUrl}/wp-json/wp/v2/posts`;

  const body: any = {
    title: article.title,
    content: article.content,
    slug: article.slug,
    status: article.date ? 'future' : 'publish',
    excerpt: article.metaDescription, // Fallback
    meta: {
      _yoast_wpseo_metadesc: article.metaDescription,
      rank_math_description: article.metaDescription
    }
  };

  if (article.date) body.date = article.date;
  if (article.category) body.categories = [article.category];
  if (article.featuredMediaId) body.featured_media = article.featuredMediaId;

  const response = await fetch(apiEndpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getAuthHeader(settings)
    },
    body: JSON.stringify(body)
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.message || 'WordPress publishing failed.');
  }

  const data = await response.json();
  return {
    link: data.link,
    id: data.id
  };
};

import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are an expert Bangla SEO content writer and Google AdSense specialist. 
    Your goal is to write a human-like, conversational, and authoritative article in Bangla.

    CRITICAL RULES:
    1. Language: Natural, clean, and professional Bangla. No robotic or obvious AI tone.
    2. Length: Minimum 1000-1200 words. Be exhaustive and detailed.
    3. Structure:
       - H1 Title: Must include Primary Keyword.
       - Intro: 150-200 words, include PK once.
       - Body: Use UPPERCASE H2 headings. Each H2 must have H3 subheadings.
       - Paragraphs: Short (2-3 sentences).
       - Lists: Use <ul> and <ol> with <li>.
       - Table: Include at least one informative HTML table.
       - FAQ: 4-5 'People Also Ask' style questions.
       - Conclusion: 100-150 words with a strong CTA.
    4. SEO Elements:
       - Meta Title (with PK).
       - Meta Description: EXACTLY 150-160 characters long. IT MUST CONTAIN THE PRIMARY KEYWORD naturally. Write it to be highly click-worthy in search results.
       - URL Slug: English translation of the Primary Keyword (lowercase, hyphenated).
       - Tags: 10-15 relevant tags (Bangla & English).
       - Featured Image Prompt: Realistic blog thumbnail description in English.
    5. HTML Formatting: Return only valid HTML for the 'content' field that can be directly used in WordPress.
  `;

  const prompt = `
    Topic: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Audience: ${params.targetAudience}

    Please write a comprehensive, high-quality, SEO-optimized article based on the instructions. 
    Make sure the Meta Description field specifically contains the keyword: "${params.primaryKeyword}" and is optimized for SEO.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          slug: { type: Type.STRING },
          content: { type: Type.STRING },
          metaTitle: { type: Type.STRING },
          metaDescription: { type: Type.STRING },
          tags: { type: Type.ARRAY, items: { type: Type.STRING } },
          featuredImagePrompt: { type: Type.STRING }
        },
        required: ["title", "slug", "content", "metaTitle", "metaDescription", "tags", "featuredImagePrompt"]
      }
    }
  });

  return JSON.parse(response.text);
};

