          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg text-white">
                <FileText size={24} />
              </div>
              <h1 className="text-xl font-bold text-gray-900 hidden sm:block">Bangla SEO AI Writer</h1>
            </div>
            <div className="flex gap-4">
              <button 
                onClick={() => setActiveTab('generate')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-medium transition-colors ${activeTab === 'generate' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:text-gray-900'}`}
              >
                <FileText size={18} /> রাইটার
              </button>
              <button 
                onClick={() => setActiveTab('settings')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-medium transition-colors ${activeTab === 'settings' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:text-gray-900'}`}
              >
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-3 text-red-700">
            <AlertCircle size={20} />
            <p>{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg flex flex-col gap-2 text-green-700">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} />
              <p className="font-semibold">সফলভাবে পোস্ট করা হয়েছে!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 underline ml-8">পোস্টটি দেখুন</a>
          </div>
        )}

        {activeTab === 'settings' ? (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden max-w-2xl mx-auto">
            <div className="p-6 border-b border-gray-100 bg-gray-50">
              <h2 className="text-lg font-bold text-gray-900">ওয়ার্ডপ্রেস পাবলিশ সেটিংস</h2>
              <p className="text-sm text-gray-500">আপনার ওয়েবসাইট লিঙ্ক ও অ্যাপ্লিকেশন পাসওয়ার্ড এখানে সেভ করুন।</p>
