import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are an expert Bangla SEO content writer and Google AdSense specialist. 
    Your goal is to write a human-like, conversational, and highly authoritative article in Bengali.

    STRICT CONTENT RULES:
    1. Language & Tone: Write in a Human-Like, Engaging Bengali tone. Use rhetorical questions and real-life examples. Avoid robotic transitions.
    2. Length Enforcement: Strictly adhere to the selected word count range: ${params.wordCountRange}.
    3. Keyword Strategy: Maintain a keyword density of approximately ${params.keywordDensity}%. Distribute the Focus Keyword "${params.primaryKeyword}" naturally.
    4. Smart English Slug: Generate a short, SEO-friendly English Slug based strictly on the Primary Keyword "${params.primaryKeyword}". 
       - It must be in English even if the content is Bengali.
       - Format: lowercase, hyphen-separated (e.g., 'gpf-balance-check-bd').
    5. FAQ Schema: Generate exactly 3 relevant Questions & Answers based on the topic. 
       - Format them as a valid JSON-LD Schema script block: <script type="application/ld+json">{ "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [...] }</script>.
       - IMPORTANT: Append this script block strictly at the very end of the HTML content string.
    6. Auto-Tagging: Generate 3-5 relevant, short tags (mixture of Bengali and English keywords).
    7. Structure:
       - H1 Title: Must include the Primary Keyword.
       - Paragraphs: Short (max 3-4 lines).
       - Lists & Table: Use <ul>/<ol> and one informative HTML table.
    8. HTML Formatting: Return valid HTML for the 'content' field.
  `;

  const prompt = `
    Topic: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Audience: ${params.targetAudience}
    Word Count Target: ${params.wordCountRange}
    Target Keyword Density: ${params.keywordDensity}%

    Write the complete SEO-optimized article. Ensure the 'slug' is in English and highly optimized. Include the FAQ Schema JSON-LD script at the bottom of the 'content' field.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          slug: { type: Type.STRING, description: 'Short English SEO slug, lowercase-hyphenated' },
          content: { type: Type.STRING, description: 'HTML content including the JSON-LD FAQ script at the end' },
          metaTitle: { type: Type.STRING },
          metaDescription: { type: Type.STRING },
          tags: { type: Type.ARRAY, items: { type: Type.STRING }, description: '3-5 relevant tags' },
          featuredImagePrompt: { type: Type.STRING }
        },
        required: ["title", "slug", "content", "metaTitle", "metaDescription", "tags", "featuredImagePrompt"]
      }
    }
  });

  return JSON.parse(response.text);
};

import { WPSettings, WPPostResponse, WPCategory } from "../types";

const getAuthHeader = (settings: WPSettings) => ({
  'Authorization': `Basic ${btoa(`${settings.username}:${settings.appPassword}`)}`
});

const getBaseUrl = (url: string) => url.endsWith('/') ? url.slice(0, -1) : url;

export const fetchCategories = async (settings: WPSettings): Promise<WPCategory[]> => {
  const baseUrl = getBaseUrl(settings.url);
  const response = await fetch(`${baseUrl}/wp-json/wp/v2/categories?per_page=100`, {
    headers: getAuthHeader(settings)
  });
  if (!response.ok) throw new Error('Failed to fetch categories');
  return response.json();
};

export interface MediaMetadata {
  title: string;
  alt_text: string;
  caption: string;
  description: string;
}

export const uploadMedia = async (settings: WPSettings, file: File, metadata: MediaMetadata): Promise<number> => {
  const baseUrl = getBaseUrl(settings.url);
  const formData = new FormData();
  formData.append('file', file);
  formData.append('title', metadata.title);
  formData.append('alt_text', metadata.alt_text);
  formData.append('caption', metadata.caption);
  formData.append('description', metadata.description);

  const response = await fetch(`${baseUrl}/wp-json/wp/v2/media`, {
    method: 'POST',
    headers: {
      ...getAuthHeader(settings)
    },
    body: formData
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message || 'Media upload failed');
  }

  const data = await response.json();
  return data.id;
};

/**
 * Creates or retrieves tag IDs from WordPress.
 * Since checking existence and creating in one go is complex, 
 * we attempt to create each tag. If it fails because it exists, 
 * we just skip it (or ideally we'd fetch it). 
 * For simplicity and UX, we'll try to create and collect successful IDs.
 */
export const ensureTags = async (settings: WPSettings, tags: string[]): Promise<number[]> => {
  const baseUrl = getBaseUrl(settings.url);
  const tagIds: number[] = [];

  for (const tagName of tags) {
    try {
      const response = await fetch(`${baseUrl}/wp-json/wp/v2/tags`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...getAuthHeader(settings)
        },
        body: JSON.stringify({ name: tagName })
      });

      const data = await response.json();
      if (response.ok) {
        tagIds.push(data.id);
      } else if (data.code === 'term_exists') {
        tagIds.push(data.data.term_id);
      }
    } catch (e) {
      console.warn(`Could not handle tag: ${tagName}`, e);
    }
  }
  return tagIds;
};

export const publishToWP = async (
  settings: WPSettings,
  article: { 
    title: string; 
    content: string; 
    slug: string; 
    date?: string; 
    category?: number;
    tags?: number[];
    metaDescription: string;
    featuredMediaId?: number;
  }
): Promise<WPPostResponse> => {
  const baseUrl = getBaseUrl(settings.url);
  const apiEndpoint = `${baseUrl}/wp-json/wp/v2/posts`;

  const body: any = {
    title: article.title,
    content: article.content,
    slug: article.slug,
    status: article.date ? 'future' : 'publish',
    excerpt: article.metaDescription,
    meta: {
      _yoast_wpseo_metadesc: article.metaDescription,
      rank_math_description: article.metaDescription
    }
  };

  if (article.date) body.date = article.date;
  if (article.category) body.categories = [article.category];
  if (article.tags && article.tags.length > 0) body.tags = article.tags;
  if (article.featuredMediaId) body.featured_media = article.featuredMediaId;

  const response = await fetch(apiEndpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getAuthHeader(settings)
    },
    body: JSON.stringify(body)
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.message || 'WordPress publishing failed.');
  }

  const data = await response.json();
  return {
    link: data.link,
    id: data.id
  };
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeyword: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeyword) {
      setError('দয়া করে টপিক এবং প্রাইমারি কিওয়ার্ড লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
