import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are an expert Bangla SEO content writer and Google AdSense specialist. 
    Your goal is to write a human-like, conversational, and highly authoritative article in Bengali.

    STRICT CONTENT RULES:
    1. Language & Tone: Write in a Human-Like, Engaging Bengali tone. Use rhetorical questions and real-life examples. Avoid robotic transitions.
    2. Length Enforcement: Strictly adhere to the selected word count range: ${params.wordCountRange}.
    3. Keyword Strategy: Maintain a keyword density of approximately ${params.keywordDensity}%. Distribute the Focus Keyword "${params.primaryKeyword}" naturally.

    HTML HEADING HIERARCHY & FLOW:
    1. NO H1 in Body: Never use <h1> tags inside the content body. The WordPress post title already serves as the H1.
    2. Main Sections (H2): Use <h2> tags for all major sections (e.g., Introduction, Main Steps, Advantages, Conclusion).
    3. Sub-Sections (H3): Use <h3> tags strictly for breaking down an H2 section into smaller steps or specific points.
    4. Avoid Deep Nesting: Do not go deeper than <h4>. Stick primarily to H2 and H3 for better scannability.
    5. Logical Flow: Start with an Introduction. Break long text blocks using H3 headers. Example: <h2>কিভাবে ব্যালেন্স চেক করবেন</h2> followed by <h3>পদ্ধতি ১: অনলাইনে</h3> and <h3>পদ্ধতি ২: এসএসএমএস এর মাধ্যমে</h3>.
    6. Header SEO: Include the Main Keyword ("${params.primaryKeyword}") or LSI keywords naturally in at least 40% of the H2 and H3 tags.

    ADDITIONAL FEATURES:
    1. Smart English Slug: Generate a short, SEO-friendly English Slug based on the Primary Keyword. Format: lowercase, hyphen-separated.
    2. FAQ Schema: Generate exactly 3 relevant Questions & Answers. Format as a valid JSON-LD Schema script block and append it strictly at the very end of the content.
    3. Auto-Tagging: Generate 3-5 relevant, short tags (mixture of Bengali and English).
    4. Structure: Paragraphs must be short (max 3-4 lines). Use <ul>/<ol> and one informative HTML table.

    STRICT FORMATTING:
    - Output raw HTML tags only.
    - DO NOT use Markdown (like ## or ###).
    - Ensure all headers are properly closed (e.g., </h2>).
  `;

  const prompt = `
    Topic: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Audience: ${params.targetAudience}
    Word Count Target: ${params.wordCountRange}
    Target Keyword Density: ${params.keywordDensity}%

    Write the complete SEO-optimized article. Strictly follow the heading hierarchy: Use H2 for main sections and H3 for subsections. Do not include any H1 tags. Ensure keywords are in headers. Include the FAQ Schema JSON-LD script at the bottom of the 'content' field.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          slug: { type: Type.STRING, description: 'Short English SEO slug, lowercase-hyphenated' },
          content: { type: Type.STRING, description: 'HTML content using H2 and H3 headers, including the JSON-LD FAQ script at the end' },
          metaTitle: { type: Type.STRING },
          metaDescription: { type: Type.STRING },
          tags: { type: Type.ARRAY, items: { type: Type.STRING }, description: '3-5 relevant tags' },
          featuredImagePrompt: { type: Type.STRING }
        },
        required: ["title", "slug", "content", "metaTitle", "metaDescription", "tags", "featuredImagePrompt"]
      }
    }
  });

  return JSON.parse(response.text);
};

