                        <option>Standard Blog (1200-1500 words)</option>
                        <option>Pillar Content (2000+ words)</option>
                      </select>
                    </div>
                    <div>
                      <div className="flex justify-between items-center mb-2">
                        <label className="block text-xs font-bold text-gray-500 uppercase">Density Target</label>
                        <span className="text-xs font-bold text-blue-600">{params.keywordDensity}%</span>
                      </div>
                      <input type="range" min="0.5" max="2.5" step="0.1" value={params.keywordDensity} onChange={(e) => setParams({...params, keywordDensity: parseFloat(e.target.value)})} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600" />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-1"><FolderTree size={14} /> ক্যাটাগরি</label>
                    <select value={selectedCategory} onChange={(e) => setSelectedCategory(Number(e.target.value))} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white">
                      <option value="">ক্যাটাগরি পছন্দ করুন...</option>
                      {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-1"><ImageIcon size={14} /> ফিচারড ইমেজ</label>
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                    <div onClick={() => fileInputRef.current?.click()} className="cursor-pointer border-2 border-dashed border-gray-300 rounded-lg p-2 text-center hover:bg-gray-50">
                      {imagePreview ? <img src={imagePreview} alt="Preview" className="h-32 w-full object-cover rounded-md" /> : <div className="py-4 text-gray-500 flex flex-col items-center"><ImageIcon size={24} className="mb-1" /><span className="text-xs">ইমেজ আপলোড করুন</span></div>}
                    </div>
                  </div>
                  <button disabled={loading} onClick={handleGenerate} className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold hover:bg-blue-700 flex items-center justify-center gap-2 disabled:opacity-50">
                    {loading ? <Loader2 size={20} className="animate-spin" /> : <FileText size={20} />} {loading ? 'জেনারেট হচ্ছে...' : 'আর্টিকেল জেনারেট করুন'}
                  </button>
                </div>
              </div>
            </div>

            <div className="lg:col-span-2 space-y-6">
              {!article && !loading && (
                <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-gray-400 bg-gray-50 border-2 border-dashed border-gray-200 rounded-xl">
                  <FileText size={48} className="mb-4 opacity-20" />
                  <p>আপনার কন্টেন্ট এখানে দেখা যাবে। বাম পাশের ফর্মটি পূরণ করে শুরু করুন।</p>
                </div>
              )}

              {loading && (
                <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-blue-600 bg-blue-50/30 border border-blue-100 rounded-xl">
                  <Loader2 size={48} className="mb-4 animate-spin" />
                  <p className="font-medium">Elite SEO কন্টেন্ট তৈরি করা হচ্ছে...</p>
                </div>
              )}

              {article && !loading && (
                <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
                  <div className="flex flex-wrap items-center justify-between gap-4 sticky top-[4.5rem] z-40 bg-white/90 backdrop-blur-md p-4 rounded-xl border border-gray-200 shadow-md">
                    <div className="flex gap-4">
                      <button disabled={publishLoading} onClick={() => handlePublish(false)} className="bg-green-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-green-700 flex items-center gap-2">
                        {publishLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />} সরাসরি পাবলিশ
                      </button>
                      <button onClick={() => setShowScheduleModal(true)} className="bg-orange-500 text-white px-6 py-2 rounded-lg font-bold hover:bg-orange-600 flex items-center gap-2">
                        <Calendar size={18} /> শিডিউল
                      </button>
                    </div>
                    {stats && (
                      <div className="flex gap-4 border-l border-gray-200 pl-4">
                        <div className="flex items-center gap-1 text-sm"><BarChart3 size={16} className="text-blue-500" /><span className="font-bold">{stats.wordCount}</span> <span className="text-gray-400">শব্দ</span></div>
                        <div className="flex items-center gap-1 text-sm"><TypeIcon size={16} className="text-purple-500" /><span className="font-bold">{stats.density}%</span> <span className="text-gray-400">ঘনত্ব</span></div>
                      </div>
                    )}
                  </div>

                  <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200">
                    <div className="mb-8 pb-8 border-b border-gray-100">
                      <div className="flex items-center gap-2 mb-4 text-xs font-bold text-green-600 uppercase tracking-widest"><ShieldCheck size={14} /> Authority Content Verified</div>
                      <h1 className="text-4xl font-bold text-gray-900 mb-6 leading-tight">{article.title}</h1>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                        <div className="p-4 bg-blue-50 rounded-xl border border-blue-100 flex items-center gap-3">
                          <Globe size={18} className="text-blue-600 shrink-0" />
                          <div><span className="block font-bold text-blue-700 mb-1 uppercase text-[10px]">Elite English Slug:</span><code className="text-blue-900 break-all font-mono">{article.slug}</code></div>
                        </div>
                        <div className="p-4 bg-purple-50 rounded-xl border border-purple-100">
                          <span className="block font-bold text-purple-700 mb-1 uppercase text-[10px]">Title Length Status:</span>
                          <span className={`${stats?.titleLength && stats.titleLength >= 55 && stats.titleLength <= 65 ? 'text-green-600' : 'text-orange-600'} font-bold`}>{stats?.titleLength} / 65 Characters</span>
                        </div>
                      </div>
                    </div>

                    <div className="space-y-6 text-gray-800 leading-relaxed preview-content prose prose-blue prose-lg max-w-none">
                       <div className="article-body-wrapper" dangerouslySetInnerHTML={{ __html: article.content }} />
                       <div className="mt-8 p-4 bg-gray-900 rounded-lg text-white font-mono text-xs overflow-auto max-h-40 border border-gray-700">
                         <div className="flex items-center gap-2 mb-2 text-gray-400 border-b border-gray-700 pb-2"><Code size={14} /> <span>FAQ Schema Detected</span></div>
                         <code>{article.faq_schema}</code>
                       </div>
                    </div>

                    <div className="mt-12 pt-8 border-t border-gray-100 bg-gray-50 -mx-8 -mb-8 p-8 rounded-b-xl">
                      <h3 className="text-lg font-bold text-gray-900 mb-6">Technical SEO Summary</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-4">
                          <div><p className="text-xs font-bold text-gray-500 uppercase mb-1">Meta Description</p><p className="text-gray-900 bg-white p-3 border border-gray-200 rounded-lg shadow-sm">{article.meta_description}</p></div>
                          <div className="bg-white p-3 rounded-lg border border-gray-200"><p className="text-xs font-bold text-gray-500 uppercase mb-1">Tags</p><div className="flex flex-wrap gap-2">{article.tags.map(t => <span key={t} className="px-2 py-1 bg-gray-100 rounded text-xs">#{t}</span>)}</div></div>
                        </div>
                        <div className="bg-white p-4 rounded-lg border border-gray-200">
                          <h4 className="text-xs font-bold text-gray-500 uppercase mb-3">Image SEO Parameters</h4>
                          <div className="space-y-2 text-sm">
                            <div className="flex justify-between"><span>Alt Text:</span> <span className="font-bold">{article.image_seo.alt_text}</span></div>
                            <div className="flex justify-between"><span>Title:</span> <span className="font-bold">{article.image_seo.title}</span></div>
                            <div className="flex justify-between"><span>Caption:</span> <span className="font-bold">{article.image_seo.caption}</span></div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {showScheduleModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden">
            <div className="p-6 border-b border-gray-100 bg-gray-50 flex justify-between items-center"><h3 className="text-xl font-bold text-gray-900">শিডিউল কনফার্ম</h3><button onClick={() => setShowScheduleModal(false)}>×</button></div>
            <div className="p-6">
              <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full px-4 py-3 border border-gray-300 rounded-xl mb-6" />
              <div className="flex gap-4">
                <button onClick={() => setShowScheduleModal(false)} className="flex-1 py-3 border rounded-xl">বাতিল</button>
                <button disabled={!scheduleDate || publishLoading} onClick={() => handlePublish(true)} className="flex-1 py-3 bg-orange-500 text-white rounded-xl font-bold hover:bg-orange-600">
                  {publishLoading ? <Loader2 className="animate-spin inline mr-2" /> : <Calendar className="inline mr-2" />} নিশ্চিত করুন
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

