  targetAudience: string;
  wordCountRange: string;
  keywordDensity: number;
}

export interface GeneratedArticle {
  title: string;
  slug: string;
  meta_description: string;
  content: string;
  faq_schema: string;
  image_seo: {
    alt_text: string;
    title: string;
    caption: string;
  };
  tags: string; // Changed from string[] to string based on elite SEO requirements
}

