  name: string;
}

export interface WPPostResponse {
  link: string;
  id: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    ROLE: You are an Elite SEO Content Strategist & Topic Authority for a Bengali Government Services Blog. Your goal is to generate a comprehensive, in-depth article that dominates search rankings and wins Featured Snippets.

    1. 🏷️ TITLE RULES (CRITICAL):
    * Structure: [Main Keyword] [Action/Benefit/Context]
    * Placement: The Main Keyword MUST be the very first words.
    * Length: Strictly 55 to 65 characters (including spaces).
    * Forbidden: NO Colons (:), Semicolons (;), Hyphens (-), "Guide" (গাইড), "Complete Guide", or Emojis.
    * Tone: Authoritative yet natural.

    2. 💡 KEY TAKEAWAYS (FEATURED SNIPPET BAIT):
    * Immediately after the first Introduction paragraph, insert a "Key Takeaways" or "একনজরে" box.
    * Format: Use a <blockquote> with a distinct style or a <div> with inline styles if necessary for readability.
    * Content: 3-4 bullet points summarizing the most important steps/info.

    3. 🏗️ CONTENT STRUCTURE & DEPTH:
    * Hierarchy: Use a logical Nested Structure (<h2> -> <h3>). NO <h1> tags in content.
    * Depth Requirement: Provide detailed steps, reasons, and analysis.
    * Mandatory H3 Count: You MUST include at least 5 to 6 <h3> tags spread across the article.
    * Keyword Injection: Include the Main Keyword ("${params.primaryKeyword}") or LSI keywords in at least 50% of the H2 and H3 headings.

    4. 📊 DATA VISUALIZATION (TABLE):
    * You MUST include at least one HTML Table in the article.
    * Content: Compare methods, fees, or summarize steps.
    * Style: Use standard HTML table tags (<table>, <tr>, <th>, <td>).

    5. 📝 CONTENT TONE (BENGALI):
    * Language: Standard Bengali (প্রমিত বাংলা).
    * Tone: Friendly, helpful, and human-like (Use "আপনি").
    * Visible FAQ Section: Add a <h2> section titled "সচরাচর জিজ্ঞাসিত প্রশ্ন (FAQ)" at the end with 3-4 Q&As.

    6. 🧩 TECHNICAL SEO:
    * image_seo: alt_text, title, and caption MUST be exactly the Main Keyword.
    * slug: Short, English, hyphen-separated based on the Main Keyword.
    * faq_schema: Valid JSON-LD Schema markup strictly matching the FAQs in the body.
    * tags: 3-5 relevant short tags as a comma-separated string.
  `;

  const prompt = `
    Topic: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Audience: ${params.targetAudience}
    Word Count Target: ${params.wordCountRange}
    Target Keyword Density: ${params.keywordDensity}%

    Generate the JSON object according to the schema. Ensure the title is exactly 55-65 characters and starts with the keyword. Follow the "Key Takeaways" and "Table" requirements strictly.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          slug: { type: Type.STRING },
          meta_description: { type: Type.STRING },
          content: { type: Type.STRING },
          faq_schema: { type: Type.STRING },
          image_seo: {
            type: Type.OBJECT,
            properties: {
              alt_text: { type: Type.STRING },
              title: { type: Type.STRING },
              caption: { type: Type.STRING }
            }
          },
          tags: { type: Type.STRING }
        },
        required: ["title", "slug", "meta_description", "content", "faq_schema", "image_seo", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code, ShieldCheck, ListChecks, Table } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeyword: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeyword) {
      setError('দয়া করে টপিক এবং প্রাইমারি কিওয়ার্ড লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        mediaId = await uploadMedia(wpSettings, selectedImage, {
          title: article.image_seo.title,
          alt_text: article.image_seo.alt_text,
          caption: article.image_seo.caption,
          description: `Representation of ${params.primaryKeyword}`
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      const finalContent = `${article.content}\n\n${article.faq_schema}`;

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: finalContent,
        slug: article.slug,
        date: isScheduling ? scheduleDate : undefined,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.meta_description,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;

    const keyword = params.primaryKeyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;

    const h2Count = (article.content.match(/<h2/g) || []).length;
    const h3Count = (article.content.match(/<h3/g) || []).length;
    const hasTable = article.content.includes('<table');
    const hasTakeaways = article.content.includes('<blockquote') || article.content.includes('একনজরে');

    return { 
      wordCount, 
      density: density.toFixed(2), 
      keywordCount,
      titleLength: article.title.length,
      h2Count,
      h3Count,
      hasTable,
      hasTakeaways
    };
  }, [article, params.primaryKeyword]);

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg text-white">
                <FileText size={24} />
              </div>
              <h1 className="text-xl font-bold text-gray-900 hidden sm:block">Bangla SEO AI Writer Pro</h1>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setActiveTab('generate')} className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-medium transition-colors ${activeTab === 'generate' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:text-gray-900'}`}>
                <FileText size={18} /> রাইটার
              </button>
              <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-medium transition-colors ${activeTab === 'settings' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:text-gray-900'}`}>
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-3 text-red-700 animate-in fade-in slide-in-from-top-2">
            <AlertCircle size={20} />
            <p>{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg flex flex-col gap-2 text-green-700 animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} />
              <p className="font-semibold">সফলভাবে পোস্ট করা হয়েছে!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 underline ml-8">পোস্টটি দেখুন</a>
          </div>
        )}

        {activeTab === 'settings' ? (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden max-w-2xl mx-auto">
            <div className="p-6 border-b border-gray-100 bg-gray-50">
