import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    ROLE: You are an Elite SEO Content Strategist & WordPress Specialist. Your task is to generate a high-ranking, in-depth article in Bengali that dominates search results.

    1. 🏗️ STRUCTURE & OUTLINE LOGIC (CRITICAL):
    * IF A CUSTOM OUTLINE IS PROVIDED:
        - You MUST follow the provided headers strictly. Do not deviate from the core flow.
        - EXPANSION RULE: To meet the Target Word Count (${params.wordCountRange}), you must deeply expand on each point. Add step-by-step instructions, bullet points, pros/cons, and real-life examples under each header. Do not just write a summary; write a detailed, authoritative guide.
    * IF NO CUSTOM OUTLINE IS PROVIDED:
        - Generate your own comprehensive structure with at least 5-6 <h3> tags and a logical flow.

    2. 📏 WORD COUNT ADHERENCE (DEPTH STRATEGY):
    - You MUST aim to hit the Target Word Count: ${params.wordCountRange}.
    - If the outline is short but the target word count is high, use the "Depth Strategy": Add comparison tables, historical context, "Why it matters" sections, and detailed "How-to" steps under existing headers to increase length without fluff.

    3. 🏷️ TITLE RULES:
    * Structure: [Main Keyword] [Action/Benefit]
    * Placement: The Main Keyword ("${params.primaryKeyword}") MUST be the very first words.
    * Length: 55-65 Characters.
    * Forbidden: NO Colons (:), "Guide", "Complete Guide", or Emojis.

    4. 📝 CONTENT BODY (HTML):
    * Format: Clean HTML (<h2>, <h3>, <p>, <ul>, <table>). NO <h1> in the body.
    * Tone: Friendly, human-like Bengali ("আপনি" style). Avoid robotic patterns.
    * Key Takeaways: Add a summary box (<blockquote>) after the first Introduction paragraph.
    * Table: Add at least one HTML table strictly related to the content.
    * FAQ: Add a visible <h2> FAQ section with 3-4 Q&As (<h3> for question, <p> for answer) at the end.

    5. 🧩 TECHNICAL SEO:
    * Slug: English, hyphen-separated based on the Main Keyword.
    * Image SEO: alt_text, title, and caption MUST be exactly "${params.primaryKeyword}".
    * Schema: Generate valid JSON-LD FAQ Schema matching the visible FAQ section.
  `;

  const prompt = `
    Topic/Keyword: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Audience: ${params.targetAudience}
    Target Word Count: ${params.wordCountRange}
    Custom Outline (if provided): ${params.customOutline || "None provided. Generate your own elite structure."}

    Return the response strictly in JSON format as specified.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          slug: { type: Type.STRING },
          meta_description: { type: Type.STRING },
          content: { type: Type.STRING },
          faq_schema: { type: Type.STRING },
          image_seo: {
            type: Type.OBJECT,
            properties: {
              alt_text: { type: Type.STRING },
              title: { type: Type.STRING },
              caption: { type: Type.STRING }
            }
          },
          tags: { type: Type.STRING }
        },
        required: ["title", "slug", "meta_description", "content", "faq_schema", "image_seo", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code, ShieldCheck, ListChecks, LayoutList, AlignLeft } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeyword: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5,
    customOutline: ''
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeyword) {
      setError('দয়া করে টপিক এবং প্রাইমারি কিওয়ার্ড লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        mediaId = await uploadMedia(wpSettings, selectedImage, {
          title: article.image_seo.title,
          alt_text: article.image_seo.alt_text,
          caption: article.image_seo.caption,
          description: `Representation of ${params.primaryKeyword}`
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      const finalContent = `${article.content}\n\n${article.faq_schema}`;

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: finalContent,
        slug: article.slug,
        date: isScheduling ? scheduleDate : undefined,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.meta_description,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;

    const keyword = params.primaryKeyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;

    const h2Count = (article.content.match(/<h2/g) || []).length;
    const h3Count = (article.content.match(/<h3/g) || []).length;
    const hasTable = article.content.includes('<table');
    const hasTakeaways = article.content.includes('<blockquote') || article.content.includes('একনজরে');

    return { 
      wordCount, 
      density: density.toFixed(2), 
      keywordCount,
      titleLength: article.title.length,
      h2Count,
      h3Count,
      hasTable,
      hasTakeaways
    };
  }, [article, params.primaryKeyword]);

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-2 rounded-lg text-white shadow-lg">
                <FileText size={24} />
              </div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-900 to-gray-600 hidden sm:block">Bangla SEO Pro</h1>
            </div>
            <div className="flex gap-2 sm:gap-4">
              <button onClick={() => setActiveTab('generate')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'generate' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <FileText size={18} /> রাইটার
              </button>
              <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'settings' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3 text-red-700 animate-in fade-in slide-in-from-top-2">
            <AlertCircle size={20} className="shrink-0" />
            <p className="font-medium">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border-l-4 border-green-500 rounded-r-lg flex flex-col gap-2 text-green-700 animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} className="shrink-0" />
              <p className="font-bold text-lg">সফলভাবে পাবলিশ হয়েছে!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 font-semibold underline ml-8 hover:text-blue-800">আপনার পোস্টটি এখানে দেখুন →</a>
          </div>
        )}

        {activeTab === 'settings' ? (
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden max-w-2xl mx-auto">
            <div className="p-6 border-b border-gray-100 bg-gray-50/50">
              <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                <Settings className="text-blue-600" size={20} /> ওয়ার্ডপ্রেস কনফিগারেশন
              </h2>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">ওয়েবসাইট URL</label>
                <input type="url" placeholder="https://example.com" value={wpSettings.url} onChange={(e) => setWpSettings({...wpSettings, url: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">ইউজারনেম</label>
                  <input type="text" placeholder="admin" value={wpSettings.username} onChange={(e) => setWpSettings({...wpSettings, username: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">অ্যাপ্লিকেশন পাসওয়ার্ড</label>
                  <input type="password" placeholder="xxxx xxxx xxxx xxxx" value={wpSettings.appPassword} onChange={(e) => setWpSettings({...wpSettings, appPassword: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
              </div>
              <button onClick={saveSettings} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2">
                <Save size={20} /> সেটিংস সেভ করুন
              </button>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-md border border-gray-100">
                <h2 className="text-lg font-bold mb-6 text-gray-900 flex items-center gap-2">
                  <AlignLeft size={22} className="text-blue-600" /> আর্টিকেল প্যারামিটারস
                </h2>
                <div className="space-y-5">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">আর্টিকেল টপিক</label>
                    <textarea rows={2} value={params.topic} onChange={(e) => setParams({...params, topic: e.target.value})} placeholder="যেমন: পাসপোর্ট রিন্যু করার নতুন নিয়ম ২০২৪" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none resize-none" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">প্রাইমারি কিওয়ার্ড</label>
                    <input type="text" value={params.primaryKeyword} onChange={(e) => setParams({...params, primaryKeyword: e.target.value})} placeholder="পাসপোর্ট রিন্যু করার নিয়ম" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>

                  <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100 space-y-4">
                     <div>
                        <label className="block text-xs font-black text-blue-800 uppercase tracking-widest mb-2">Target Length</label>
                        <select value={params.wordCountRange} onChange={(e) => setParams({...params, wordCountRange: e.target.value})} className="w-full px-3 py-2.5 text-sm border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 bg-white font-medium">
                          <option>Short (800-1000 words)</option>
                          <option>Standard (1200-1500 words)</option>
                          <option>Long Form (2000-2500 words)</option>
                          <option>Epic Pillar (3000+ words)</option>
                        </select>
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-blue-900 mb-2 flex items-center gap-2">
                           <LayoutList size={16} /> কাস্টম আউটলাইন (ঐচ্ছিক)
                        </label>
                        <textarea 
                           rows={4} 
                           value={params.customOutline} 
                           onChange={(e) => setParams({...params, customOutline: e.target.value})} 
                           placeholder="হেডার ১, হেডার ২ এভাবে কাস্টম আউটলাইন দিতে পারেন..." 
                           className="w-full px-4 py-3 border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm resize-y" 
                        />
                        <p className="text-[10px] text-blue-600 mt-1 italic">আউটলাইন দিলে AI এটি কঠোরভাবে মেনে আর্টিকেল বড় করবে।</p>
                     </div>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1">
                      <FolderTree size={16} /> ক্যাটাগরি
                    </label>
                    <select value={selectedCategory} onChange={(e) => setSelectedCategory(Number(e.target.value))} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white">
                      <option value="">সিলেক্ট করুন...</option>
                      {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1">
                      <ImageIcon size={16} /> ফিচারড ইমেজ
                    </label>
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                    <div onClick={() => fileInputRef.current?.click()} className="group cursor-pointer border-2 border-dashed border-gray-200 rounded-2xl p-2 text-center hover:border-blue-400 hover:bg-blue-50/50 transition-all">
                      {imagePreview ? (
                        <div className="relative">
                           <img src={imagePreview} alt="Preview" className="h-40 w-full object-cover rounded-xl shadow-inner" />
                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-bold rounded-xl transition-opacity">ছবি পরিবর্তন করুন</div>
                        </div>
                      ) : (
                        <div className="py-6 text-gray-400 flex flex-col items-center">
                          <ImageIcon size={32} className="mb-2 opacity-50" />
                          <span className="text-sm font-medium">ডিভাইস থেকে ছবি আপলোড করুন</span>
                        </div>
                      )}
                    </div>
                  </div>

                  <button disabled={loading} onClick={handleGenerate} className="w-full bg-gradient-to-r from-blue-600 to-indigo-700 text-white py-4 rounded-xl font-bold hover:shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:scale-100">
                    {loading ? <Loader2 size={24} className="animate-spin" /> : <FileText size={24} />} 
                    {loading ? 'আর্টিকেল লেখা হচ্ছে...' : 'জেনারেট আর্টিকেল'}
                  </button>
                </div>
              </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
              {!article && !loading && (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-gray-400 bg-white border border-gray-100 rounded-3xl shadow-sm px-10">
                  <div className="bg-gray-50 p-6 rounded-full mb-6">
                    <FileText size={64} className="opacity-10" />
                  </div>
                  <h3 className="text-xl font-bold text-gray-800 mb-2">আর্টিকেল প্রিভিউ</h3>
                  <p className="text-center max-w-sm">বাম পাশের ফরমটি পূরণ করে কন্টেন্ট জেনারেশন শুরু করুন। AI আপনার জন্য ইন-ডেপথ এবং এসইও অপ্টিমাইজড কন্টেন্ট তৈরি করবে।</p>
                </div>
              )}

              {loading && (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-blue-600 bg-white border border-gray-100 rounded-3xl shadow-sm px-10">
                  <div className="relative mb-8">
                     <Loader2 size={80} className="animate-spin opacity-20" />
                     <FileText size={32} className="absolute inset-0 m-auto animate-pulse" />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 mb-3 animate-pulse">ম্যাজিক কন্টেন্ট তৈরি হচ্ছে...</h3>
                  <p className="text-gray-500 font-medium text-center max-w-md">আপনার ইনপুট এবং আউটলাইন অনুযায়ী Gemini 3 Pro কন্টেন্ট সাজাচ্ছে। এতে ৪৫-৯০ সেকেন্ড সময় লাগতে পারে।</p>
                </div>
              )}

              {article && !loading && (
                <div className="space-y-6 animate-in slide-in-from-bottom-8 duration-700">
                  <div className="flex flex-wrap items-center justify-between gap-4 sticky top-[4.5rem] z-40 bg-white/80 backdrop-blur-xl p-5 rounded-3xl border border-gray-100 shadow-xl">
                    <div className="flex gap-3">
                      <button disabled={publishLoading} onClick={() => handlePublish(false)} className="bg-green-600 text-white px-8 py-3 rounded-2xl font-bold hover:bg-green-700 hover:shadow-lg transition-all flex items-center gap-2 active:scale-95 disabled:opacity-50">
                        {publishLoading ? <Loader2 size={20} className="animate-spin" /> : <Send size={20} />} সরাসরি পাবলিশ
                      </button>
                      <button onClick={() => setShowScheduleModal(true)} className="bg-orange-500 text-white px-8 py-3 rounded-2xl font-bold hover:bg-orange-600 hover:shadow-lg transition-all flex items-center gap-2 active:scale-95">
                        <Calendar size={20} /> শিডিউল
                      </button>
                    </div>
                    {stats && (
                      <div className="flex flex-wrap gap-4 items-center bg-gray-50 p-2 rounded-2xl border border-gray-100">
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-white rounded-xl shadow-sm border border-gray-100">
                           <BarChart3 size={18} className="text-blue-500" />
                           <span className="font-bold text-gray-800">{stats.wordCount}</span> 
                           <span className="text-xs text-gray-400 font-bold uppercase tracking-tighter">শব্দ</span>
                        </div>
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-white rounded-xl shadow-sm border border-gray-100">
                           <TypeIcon size={18} className="text-purple-500" />
                           <span className="font-bold text-gray-800">{stats.density}%</span> 
                           <span className="text-xs text-gray-400 font-bold uppercase tracking-tighter">ঘনত্ব</span>
                        </div>
                        <div className={`px-3 py-1 rounded-xl text-xs font-black uppercase tracking-widest ${stats.h3Count >= 5 ? 'bg-green-500 text-white' : 'bg-red-500 text-white shadow-lg'}`}>
                           H3: {stats.h3Count}/5
                        </div>
                      </div>
                    )}
                  </div>

                  <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-gray-50 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-blue-50 rounded-bl-full -z-0 opacity-50" />

                    <div className="relative z-10">
                      <div className="mb-10 pb-10 border-b border-gray-100">
                        <div className="flex items-center gap-2 mb-6 text-xs font-black text-blue-600 uppercase tracking-[0.2em] bg-blue-50 w-fit px-4 py-1.5 rounded-full"><ShieldCheck size={16} /> Authority Verified Content</div>
                        <h1 className="text-5xl font-black text-gray-900 mb-8 leading-tight tracking-tight">{article.title}</h1>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-sm">
                          <div className="p-5 bg-blue-50/50 rounded-3xl border border-blue-100 flex items-center gap-4 transition-transform hover:scale-[1.02]">
                            <Globe size={24} className="text-blue-600 shrink-0" />
                            <div>
                               <span className="block font-black text-blue-800 mb-1 uppercase text-[10px] tracking-widest">Elite Slug</span>
                               <code className="text-blue-900 break-all font-mono font-bold bg-white px-2 py-0.5 rounded border border-blue-100">{article.slug}</code>
                            </div>
                          </div>
                          <div className="p-5 bg-purple-50/50 rounded-3xl border border-purple-100 transition-transform hover:scale-[1.02]">
                            <span className="block font-black text-purple-800 mb-1 uppercase text-[10px] tracking-widest">Title SEO Score</span>
                            <div className="flex items-center gap-3">
                               <div className="flex-grow h-2 bg-gray-200 rounded-full overflow-hidden">
                                  <div className={`h-full transition-all duration-1000 ${stats?.titleLength && stats.titleLength >= 55 && stats.titleLength <= 65 ? 'bg-green-500' : 'bg-orange-500'}`} style={{ width: `${Math.min(100, (stats?.titleLength || 0) * 1.5)}%` }} />
                               </div>
                               <span className="font-black text-gray-900">{stats?.titleLength} / 65</span>
                            </div>
                          </div>
                        </div>
                      </div>

                      <div className="space-y-8 text-gray-800 leading-[1.8] preview-content prose prose-blue prose-lg max-w-none prose-h2:font-black prose-h2:text-3xl prose-h3:font-bold prose-h3:text-2xl prose-p:font-medium">
                         {stats?.hasTakeaways && (
                            <div className="bg-gradient-to-br from-yellow-50 to-orange-50 border-l-[6px] border-orange-400 p-8 mb-10 rounded-r-3xl shadow-sm">
                               <div className="flex items-center gap-3 mb-4 text-orange-800 font-black uppercase tracking-widest text-sm">
                                  <ListChecks size={24} /> একনজরে (Key Takeaways)
                               </div>
                               <div className="text-orange-900 font-semibold italic text-lg leading-relaxed">Featured Snippet অপ্টিমাইজড কন্টেন্ট পাওয়া গেছে। এটি গুগলের জিরো পজিশনে র‍্যাংক করতে সাহায্য করবে।</div>
                            </div>
                         )}
                         <div className="article-body-wrapper" dangerouslySetInnerHTML={{ __html: article.content }} />

                         <div className="mt-12 bg-gray-900 rounded-[2rem] p-8 text-white shadow-2xl relative">
                            <div className="flex items-center justify-between mb-6 border-b border-gray-800 pb-4">
                               <div className="flex items-center gap-3 font-bold text-gray-400 uppercase tracking-widest text-xs">
                                  <Code size={18} className="text-blue-400" /> FAQ Schema Detected
                               </div>
                               <div className="bg-blue-600/20 text-blue-400 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border border-blue-500/30">JSON-LD READY</div>
                            </div>
                            <pre className="text-xs font-mono text-blue-300 overflow-auto max-h-48 scrollbar-hide">
                               <code>{article.faq_schema}</code>
                            </pre>
                         </div>
                      </div>

                      <div className="mt-16 pt-10 border-t border-gray-100 bg-gray-50/80 -mx-10 -mb-10 p-10 rounded-b-[2.5rem]">
                        <h3 className="text-2xl font-black text-gray-900 mb-8 flex items-center gap-3">
                           <ShieldCheck className="text-blue-600" size={28} /> SEO হেলথ অডিট
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                          <div className="space-y-6">
                            <div>
                               <p className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-3">Meta Description (Snippet)</p>
                               <div className="bg-white p-6 border border-gray-200 rounded-3xl shadow-sm text-sm font-medium text-gray-700 leading-relaxed italic">
                                  "{article.meta_description}"
                               </div>
                            </div>
                            <div>
                               <p className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-3">Elite Topic Tags</p>
                               <div className="flex flex-wrap gap-2">
                                  {article.tags.split(',').map((t, idx) => (
                                     <span key={idx} className="px-4 py-2 bg-white rounded-2xl text-xs font-bold text-blue-700 border border-blue-100 shadow-sm transition-transform hover:scale-110">
                                        #{t.trim()}
                                     </span>
                                  ))}
                               </div>
                            </div>
                          </div>
                          <div className="bg-white p-8 rounded-[2rem] border border-gray-200 shadow-sm space-y-5">
                            <h4 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-4">Snippet Optimization Checklist</h4>
                            <div className="space-y-4">
                              <div className="flex justify-between items-center text-sm font-bold">
                                 <span className="text-gray-600 flex items-center gap-2"><ListChecks size={16} className="text-orange-500" /> Takeaways Box:</span> 
                                 <span className={stats?.hasTakeaways ? 'text-green-600' : 'text-red-500'}>{stats?.hasTakeaways ? '✅ detected' : '❌ missing'}</span>
                              </div>
                              <div className="flex justify-between items-center text-sm font-bold">
                                 <span className="text-gray-600 flex items-center gap-2"><Table size={16} className="text-blue-500" /> Data Visual Table:</span> 
                                 <span className={stats?.hasTable ? 'text-green-600' : 'text-red-500'}>{stats?.hasTable ? '✅ present' : '❌ missing'}</span>
                              </div>
                              <div className="flex justify-between items-center text-sm font-bold">
                                 <span className="text-gray-600 flex items-center gap-2"><ImageIcon size={16} className="text-purple-500" /> Image Alt Tags:</span> 
                                 <span className="text-blue-600">SEO Optimized</span>
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {showScheduleModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md transition-all animate-in fade-in duration-300">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full overflow-hidden border border-gray-100 transform animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
               <h3 className="text-2xl font-black text-gray-900">পোস্ট শিডিউল</h3>
               <button onClick={() => setShowScheduleModal(false)} className="text-gray-400 hover:text-gray-900 text-3xl font-light">&times;</button>
            </div>
            <div className="p-10">
              <label className="block text-sm font-bold text-gray-700 mb-4 uppercase tracking-widest text-center">সময় সিলেক্ট করুন</label>
              <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full px-5 py-4 border-2 border-gray-100 rounded-2xl mb-8 outline-none focus:border-blue-500 transition-all text-center text-lg font-bold" />
              <div className="flex gap-4">
                <button onClick={() => setShowScheduleModal(false)} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-500 hover:bg-gray-50 transition-all">বাতিল</button>
                <button disabled={!scheduleDate || publishLoading} onClick={() => handlePublish(true)} className="flex-1 py-4 bg-gradient-to-r from-orange-500 to-red-600 text-white rounded-2xl font-black hover:shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2">
                  {publishLoading ? <Loader2 className="animate-spin" size={20} /> : <Calendar size={20} />} নিশ্চিত করুন
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
// Added Table to the imports from lucide-react
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code, ShieldCheck, ListChecks, LayoutList, AlignLeft, Table } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeyword: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5,
    customOutline: ''
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeyword) {
      setError('দয়া করে টপিক এবং প্রাইমারি কিওয়ার্ড লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        mediaId = await uploadMedia(wpSettings, selectedImage, {
          title: article.image_seo.title,
          alt_text: article.image_seo.alt_text,
          caption: article.image_seo.caption,
          description: `Representation of ${params.primaryKeyword}`
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      const finalContent = `${article.content}\n\n${article.faq_schema}`;

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: finalContent,
        slug: article.slug,
        date: isScheduling ? scheduleDate : undefined,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.meta_description,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;

    const keyword = params.primaryKeyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;

    const h2Count = (article.content.match(/<h2/g) || []).length;
    const h3Count = (article.content.match(/<h3/g) || []).length;
    const hasTable = article.content.includes('<table');
    const hasTakeaways = article.content.includes('<blockquote') || article.content.includes('একনজরে');

    return { 
      wordCount, 
      density: density.toFixed(2), 
      keywordCount,
      titleLength: article.title.length,
      h2Count,
      h3Count,
      hasTable,
      hasTakeaways
    };
  }, [article, params.primaryKeyword]);

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-2 rounded-lg text-white shadow-lg">
                <FileText size={24} />
              </div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-900 to-gray-600 hidden sm:block">Bangla SEO Pro</h1>
            </div>
            <div className="flex gap-2 sm:gap-4">
              <button onClick={() => setActiveTab('generate')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'generate' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <FileText size={18} /> রাইটার
              </button>
              <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'settings' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3 text-red-700 animate-in fade-in slide-in-from-top-2">
            <AlertCircle size={20} className="shrink-0" />
            <p className="font-medium">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border-l-4 border-green-500 rounded-r-lg flex flex-col gap-2 text-green-700 animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} className="shrink-0" />
              <p className="font-bold text-lg">সফলভাবে পাবলিশ হয়েছে!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 font-semibold underline ml-8 hover:text-blue-800">আপনার পোস্টটি এখানে দেখুন →</a>
          </div>
        )}

        {activeTab === 'settings' ? (
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden max-w-2xl mx-auto">
            <div className="p-6 border-b border-gray-100 bg-gray-50/50">
              <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                <Settings className="text-blue-600" size={20} /> ওয়ার্ডপ্রেস কনফিগারেশন
              </h2>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">ওয়েবসাইট URL</label>
                <input type="url" placeholder="https://example.com" value={wpSettings.url} onChange={(e) => setWpSettings({...wpSettings, url: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">ইউজারনেম</label>
                  <input type="text" placeholder="admin" value={wpSettings.username} onChange={(e) => setWpSettings({...wpSettings, username: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">অ্যাপ্লিকেশন পাসওয়ার্ড</label>
                  <input type="password" placeholder="xxxx xxxx xxxx xxxx" value={wpSettings.appPassword} onChange={(e) => setWpSettings({...wpSettings, appPassword: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
              </div>
              <button onClick={saveSettings} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2">
                <Save size={20} /> সেটিংস সেভ করুন
              </button>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-md border border-gray-100">
                <h2 className="text-lg font-bold mb-6 text-gray-900 flex items-center gap-2">
                  <AlignLeft size={22} className="text-blue-600" /> আর্টিকেল প্যারামিটারস
                </h2>
                <div className="space-y-5">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">আর্টিকেল টপিক</label>
                    <textarea rows={2} value={params.topic} onChange={(e) => setParams({...params, topic: e.target.value})} placeholder="যেমন: পাসপোর্ট রিন্যু করার নতুন নিয়ম ২০২৪" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none resize-none" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">প্রাইমারি কিওয়ার্ড</label>
                    <input type="text" value={params.primaryKeyword} onChange={(e) => setParams({...params, primaryKeyword: e.target.value})} placeholder="পাসপোর্ট রিন্যু করার নিয়ম" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>

                  <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100 space-y-4">
                     <div>
                        <label className="block text-xs font-black text-blue-800 uppercase tracking-widest mb-2">Target Length</label>
                        <select value={params.wordCountRange} onChange={(e) => setParams({...params, wordCountRange: e.target.value})} className="w-full px-3 py-2.5 text-sm border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 bg-white font-medium">
                          <option>Short (800-1000 words)</option>
                          <option>Standard (1200-1500 words)</option>
                          <option>Long Form (2000-2500 words)</option>
                          <option>Epic Pillar (3000+ words)</option>
                        </select>
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-blue-900 mb-2 flex items-center gap-2">
                           <LayoutList size={16} /> কাস্টম আউটলাইন (ঐচ্ছিক)
                        </label>
                        <textarea 
                           rows={4} 
                           value={params.customOutline} 
                           onChange={(e) => setParams({...params, customOutline: e.target.value})} 
                           placeholder="হেডার ১, হেডার ২ এভাবে কাস্টম আউটলাইন দিতে পারেন..." 
                           className="w-full px-4 py-3 border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm resize-y" 
                        />
                        <p className="text-[10px] text-blue-600 mt-1 italic">আউটলাইন দিলে AI এটি কঠোরভাবে মেনে আর্টিকেল বড় করবে।</p>
                     </div>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1">
                      <FolderTree size={16} /> ক্যাটাগরি
                    </label>
                    <select value={selectedCategory} onChange={(e) => setSelectedCategory(Number(e.target.value))} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white">
                      <option value="">সিলেক্ট করুন...</option>
                      {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1">
                      <ImageIcon size={16} /> ফিচারড ইমেজ
                    </label>
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                    <div onClick={() => fileInputRef.current?.click()} className="group cursor-pointer border-2 border-dashed border-gray-200 rounded-2xl p-2 text-center hover:border-blue-400 hover:bg-blue-50/50 transition-all">
                      {imagePreview ? (
                        <div className="relative">
                           <img src={imagePreview} alt="Preview" className="h-40 w-full object-cover rounded-xl shadow-inner" />
                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-bold rounded-xl transition-opacity">ছবি পরিবর্তন করুন</div>
                        </div>
                      ) : (
                        <div className="py-6 text-gray-400 flex flex-col items-center">
                          <ImageIcon size={32} className="mb-2 opacity-50" />
                          <span className="text-sm font-medium">ডিভাইস থেকে ছবি আপলোড করুন</span>
                        </div>
                      )}
                    </div>
                  </div>

                  <button disabled={loading} onClick={handleGenerate} className="w-full bg-gradient-to-r from-blue-600 to-indigo-700 text-white py-4 rounded-xl font-bold hover:shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:scale-100">
                    {loading ? <Loader2 size={24} className="animate-spin" /> : <FileText size={24} />} 
                    {loading ? 'আর্টিকেল লেখা হচ্ছে...' : 'জেনারেট আর্টিকেল'}
                  </button>
                </div>
              </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
              {!article && !loading && (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-gray-400 bg-white border border-gray-100 rounded-3xl shadow-sm px-10">
                  <div className="bg-gray-50 p-6 rounded-full mb-6">
