import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    ROLE: You are an Elite SEO Specialist & WordPress Automation Expert. Your goal is to generate Bengali content that scores 90/100 on Yoast SEO analysis.

    STRICT YOAST SEO RULES:

    1. 🎯 FOCUS KEYPHRASE (CRITICAL):
    * Focus Keyphrase: "${params.primaryKeyword}".
    * You MUST place this keyphrase in:
        - The WordPress Title.
        - The SEO Title (Start with it).
        - The very first sentence of the Meta Description.
        - The very first paragraph of the Content.
        - At least 50% of H2 and H3 subheadings.
        - The Image Alt Text.

    2. 🏷️ YOAST SEO METADATA:
    * SEO Title: "[Focus Keyphrase] [Power Word/Benefit]".
        - Length: Strictly 50-60 characters.
        - Must start with the Focus Keyphrase.
    * Meta Description: Write a high-CTR summary.
        - Length: Strictly 135-155 characters.
        - Must include the exact Focus Keyphrase in the first sentence.

    3. 📝 CONTENT OPTIMIZATION:
    * Structure: Clean HTML (<h2>, <h3>, <p>, <ul>, <table>). NO <h1> in body.
    * Length: Meet Target Word Count: ${params.wordCountRange}.
    * Readability: Short sentences (under 20 words), active voice, and clear transitions.
    * Elements: 
        - Intro with Focus Keyphrase.
        - Summary block (<blockquote>) after Intro.
        - Detailed H2/H3 sections (at least 5-6 H3s).
        - At least one data table (<table>).
        - Visible FAQ section at the end (<h2> FAQ title, <h3> questions, <p> answers).

    4. 🧩 TECHNICAL SEO:
    * Slug: Short, English, hyphen-separated version of the Focus Keyphrase.
    * Image SEO: Alt/Caption must be exactly "${params.primaryKeyword}".
    * Schema: Generate valid JSON-LD FAQ Schema matching the visible FAQ section.
  `;

  const prompt = `
    Topic: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Custom Outline: ${params.customOutline || "None provided. Create elite structure."}

    Return a single valid JSON object strictly matching the schema.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING },
          slug: { type: Type.STRING },
          yoast_seo: {
            type: Type.OBJECT,
            properties: {
              focus_keyword: { type: Type.STRING },
              seo_title: { type: Type.STRING },
              meta_desc: { type: Type.STRING }
            }
          },
          image_seo: {
            type: Type.OBJECT,
            properties: {
              alt: { type: Type.STRING },
              caption: { type: Type.STRING }
            }
          },
          faq_schema: { type: Type.STRING },
          tags: { type: Type.STRING }
        },
        required: ["title", "content", "slug", "yoast_seo", "image_seo", "faq_schema", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

import { WPSettings, WPPostResponse, WPCategory } from "../types";

const getAuthHeader = (settings: WPSettings) => ({
  'Authorization': `Basic ${btoa(`${settings.username}:${settings.appPassword}`)}`
});

const getBaseUrl = (url: string) => url.endsWith('/') ? url.slice(0, -1) : url;

export const fetchCategories = async (settings: WPSettings): Promise<WPCategory[]> => {
  const baseUrl = getBaseUrl(settings.url);
  const response = await fetch(`${baseUrl}/wp-json/wp/v2/categories?per_page=100`, {
    headers: getAuthHeader(settings)
  });
  if (!response.ok) throw new Error('Failed to fetch categories');
  return response.json();
};

export interface MediaMetadata {
  title: string;
  alt_text: string;
  caption: string;
  description: string;
}

export const uploadMedia = async (settings: WPSettings, file: File, metadata: MediaMetadata): Promise<number> => {
  const baseUrl = getBaseUrl(settings.url);
  const formData = new FormData();
  formData.append('file', file);
  formData.append('title', metadata.title);
  formData.append('alt_text', metadata.alt_text);
  formData.append('caption', metadata.caption);
  formData.append('description', metadata.description);

  const response = await fetch(`${baseUrl}/wp-json/wp/v2/media`, {
    method: 'POST',
    headers: {
      ...getAuthHeader(settings)
    },
    body: formData
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message || 'Media upload failed');
  }

  const data = await response.json();
  return data.id;
};

export const ensureTags = async (settings: WPSettings, tags: string[]): Promise<number[]> => {
  const baseUrl = getBaseUrl(settings.url);
  const tagIds: number[] = [];

  for (const tagName of tags) {
    try {
      const response = await fetch(`${baseUrl}/wp-json/wp/v2/tags`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...getAuthHeader(settings)
        },
        body: JSON.stringify({ name: tagName })
      });

      const data = await response.json();
      if (response.ok) {
        tagIds.push(data.id);
      } else if (data.code === 'term_exists') {
        tagIds.push(data.data.term_id);
      }
    } catch (e) {
      console.warn(`Could not handle tag: ${tagName}`, e);
    }
  }
  return tagIds;
};

export const publishToWP = async (
  settings: WPSettings,
  article: { 
    title: string; 
    content: string; 
    slug: string; 
    date?: string; 
    category?: number;
    tags?: number[];
    metaDescription: string;
    focusKeyword: string;
    seoTitle: string;
    featuredMediaId?: number;
  }
): Promise<WPPostResponse> => {
  const baseUrl = getBaseUrl(settings.url);
  const apiEndpoint = `${baseUrl}/wp-json/wp/v2/posts`;

  const body: any = {
    title: article.title,
    content: article.content,
    slug: article.slug,
    status: article.date ? 'future' : 'publish',
    excerpt: article.metaDescription,
    // Yoast SEO Specific Metadata Keys
    meta: {
      _yoast_wpseo_focuskw: article.focusKeyword,
      _yoast_wpseo_title: article.seoTitle,
      _yoast_wpseo_metadesc: article.metaDescription,
      rank_math_description: article.metaDescription // Also support Rank Math as fallback
    }
  };

  if (article.date) body.date = article.date;
  if (article.category) body.categories = [article.category];
  if (article.tags && article.tags.length > 0) body.tags = article.tags;
  if (article.featuredMediaId) body.featured_media = article.featuredMediaId;

  const response = await fetch(apiEndpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getAuthHeader(settings)
    },
    body: JSON.stringify(body)
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.message || 'WordPress publishing failed.');
  }

  const data = await response.json();
  return {
    link: data.link,
    id: data.id
  };
};

