                <button disabled={!scheduleDate || publishLoading} onClick={() => handlePublish(true)} className="flex-1 py-4 bg-orange-500 text-white rounded-2xl font-black hover:shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2">
                  {publishLoading ? <Loader2 className="animate-spin" size={20} /> : <Calendar size={20} />} শিডিউল করুন
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

