import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    ROLE: You are an Elite SEO Specialist & WordPress Automation Expert. Your goal is to generate Bengali content that scores 90/100 on Yoast SEO analysis.

    STRICT YOAST SEO RULES:

    1. 🎯 FOCUS KEYPHRASE (CRITICAL):
    * Focus Keyphrase: "${params.primaryKeyword}".
    * You MUST place this keyphrase in:
        - The WordPress Title.
        - The SEO Title (Start with it).
        - The very first sentence of the Meta Description.
        - The very first paragraph of the Content.
        - At least 50% of H2 and H3 subheadings.
        - The Image Alt Text.

    2. 🏷️ YOAST SEO METADATA:
    * SEO Title: "[Focus Keyphrase] [Power Word/Benefit]".
        - Length: Strictly 50-60 characters.
        - Must start with the Focus Keyphrase.
    * Meta Description: Write a high-CTR summary.
        - Length: Strictly 135-155 characters.
        - Must include the exact Focus Keyphrase in the first sentence.

    3. 📝 CONTENT OPTIMIZATION:
    * Structure: Clean HTML (<h2>, <h3>, <p>, <ul>, <table>). NO <h1> in body.
    * Length: Meet Target Word Count: ${params.wordCountRange}.
    * Readability: Short sentences (under 20 words), active voice, and clear transitions.
    * Elements: 
        - Intro with Focus Keyphrase.
        - Summary block (<blockquote>) after Intro.
        - Detailed H2/H3 sections (at least 5-6 H3s).
        - At least one data table (<table>).

    4. 🧩 TECHNICAL SEO:
    * Slug: Short, English, hyphen-separated version of the Focus Keyphrase.
    * Image SEO: Alt/Caption must be exactly "${params.primaryKeyword}".
  `;

  const prompt = `
    Topic: ${params.topic}
    Primary Keyword: ${params.primaryKeyword}
    Custom Outline: ${params.customOutline || "None provided. Create elite structure."}

    Return a single valid JSON object strictly matching the schema.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING },
          slug: { type: Type.STRING },
          yoast_seo: {
            type: Type.OBJECT,
            properties: {
              focus_keyword: { type: Type.STRING },
              seo_title: { type: Type.STRING },
              meta_desc: { type: Type.STRING }
            }
          },
          image_seo: {
            type: Type.OBJECT,
            properties: {
              alt: { type: Type.STRING },
              caption: { type: Type.STRING }
            }
          },
          tags: { type: Type.STRING }
        },
        required: ["title", "content", "slug", "yoast_seo", "image_seo", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code, ShieldCheck, ListChecks, LayoutList, AlignLeft, Table, Target } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeyword: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5,
    customOutline: ''
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeyword) {
      setError('দয়া করে টপিক এবং প্রাইমারি কিওয়ার্ড লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        mediaId = await uploadMedia(wpSettings, selectedImage, {
          title: article.image_seo.alt, // Use alt as title for better SEO
          alt_text: article.image_seo.alt,
          caption: article.image_seo.caption,
          description: `Representation of ${article.yoast_seo.focus_keyword}`
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: article.content,
        slug: article.slug,
        date: isScheduling ? scheduleDate : undefined,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.yoast_seo.meta_desc,
        focusKeyword: article.yoast_seo.focus_keyword,
        seoTitle: article.yoast_seo.seo_title,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;

    const keyword = article.yoast_seo.focus_keyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;

    const h2Count = (article.content.match(/<h2/g) || []).length;
    const h3Count = (article.content.match(/<h3/g) || []).length;
    const hasTable = article.content.includes('<table');
    const hasTakeaways = article.content.includes('<blockquote') || article.content.includes('একনজরে');

    return { 
      wordCount, 
      density: density.toFixed(2), 
      keywordCount,
      seoTitleLength: article.yoast_seo.seo_title.length,
      metaDescLength: article.yoast_seo.meta_desc.length,
      h2Count,
      h3Count,
      hasTable,
      hasTakeaways
    };
  }, [article]);

  return (
    <div className="min-h-screen flex flex-col">
