                            <div className="space-y-4">
                                <div className="bg-white p-5 rounded-3xl border border-gray-200 shadow-sm">
                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Focus Keyphrase</p>
