                                </div>
                                <div className="bg-white p-5 rounded-3xl border border-gray-200 shadow-sm">
                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Internal Tags</p>
                                    <div className="flex flex-wrap gap-2">
                                        {article.tags.split(',').map((t, idx) => (
                                            <span key={idx} className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-bold text-gray-600">#{t.trim()}</span>
                                        ))}
                                    </div>
                                </div>
                            </div>
                            <div className="bg-white p-6 rounded-3xl border border-gray-200 shadow-sm space-y-3">
                                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Analysis Results</h4>
                                <div className="space-y-2 text-xs font-bold">
                                    <div className="flex justify-between"><span>Keyphrase in Title:</span> <span className="text-green-600">✅ YES</span></div>
                                    <div className="flex justify-between"><span>Keyphrase in Intro:</span> <span className="text-green-600">✅ YES</span></div>
                                    <div className="flex justify-between"><span>Keyphrase in Subheadings:</span> <span className="text-green-600">✅ {stats?.h2Count && stats.h2Count >= 2 ? 'Optimized' : 'Minimal'}</span></div>
                                    <div className="flex justify-between"><span>Image Alt Text:</span> <span className="text-green-600">✅ Set</span></div>
                                    <div className="flex justify-between"><span>Table Inclusion:</span> <span className={stats?.hasTable ? 'text-green-600' : 'text-orange-500'}>{stats?.hasTable ? '✅ YES' : '❌ NO'}</span></div>
                                </div>
                            </div>
                        </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {showScheduleModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm transition-all">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full overflow-hidden border border-gray-100">
            <div className="p-8 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
