import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    ROLE: You are an Elite SEO Specialist & WordPress Automation Expert. Your goal is to generate Bengali content that scores 90/100 on Yoast SEO analysis by integrating multiple keyphrases.

    STRICT YOAST SEO RULES:

    1. 🎯 FOCUS KEYPHRASES (CRITICAL):
    * Primary Main Keywords: "${params.primaryKeywords}".
    * Secondary Keywords: "${params.secondaryKeywords}".
    * Optimization Strategy:
        - Identify the most potent keyphrase from the Main Keywords as the "Focus Keyphrase".
        - Use the other Main and Secondary keywords naturally throughout the text as "Related Keyphrases".
        - Focus Keyphrase MUST be in: WordPress Title, SEO Title (start with it), first sentence of Meta Description, first paragraph of content, at least 50% of H2/H3 subheadings, and Image Alt Text.

    2. 🏷️ YOAST SEO METADATA:
    * SEO Title: "[Focus Keyphrase] [Power Word/Benefit]".
        - Length: Strictly 50-60 characters.
        - Must start with the main Focus Keyphrase.
    * Meta Description: High-CTR summary.
        - Length: Strictly 135-155 characters.
        - Must include the exact main Focus Keyphrase in the first sentence.

    3. 📝 CONTENT OPTIMIZATION:
    * Structure: Clean HTML (<h2>, <h3>, <p>, <ul>, <table>). NO <h1> in body.
    * Length: Meet Target Word Count: ${params.wordCountRange}.
    * Readability: Short sentences (under 20 words), active voice, and logical transitions.
    * Elements: 
        - Intro with Focus Keyphrase.
        - Summary block (<blockquote>) after Intro.
        - Strategic placement of Related Keyphrases in subheadings and body.
        - Detailed H2/H3 sections (at least 5-6 H3s).
        - At least one data-rich HTML table (<table>).

    4. 🧩 TECHNICAL SEO:
    * Slug: Short, English, hyphen-separated based on the main Focus Keyphrase.
    * Image SEO: Alt/Caption must strictly match the main Focus Keyphrase.
  `;

  const prompt = `
    Topic: ${params.topic}
    Main Keywords: ${params.primaryKeywords}
    Secondary Keywords: ${params.secondaryKeywords}
    Custom Outline: ${params.customOutline || "None provided. Create elite structure."}

    Return a single valid JSON object strictly matching the schema. Ensure all keywords are woven into the Bengali content with high authority.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING },
          slug: { type: Type.STRING },
          yoast_seo: {
            type: Type.OBJECT,
            properties: {
              focus_keyword: { type: Type.STRING },
              seo_title: { type: Type.STRING },
              meta_desc: { type: Type.STRING }
            }
          },
          image_seo: {
            type: Type.OBJECT,
            properties: {
              alt: { type: Type.STRING },
              caption: { type: Type.STRING }
            }
          },
          tags: { type: Type.STRING }
        },
        required: ["title", "content", "slug", "yoast_seo", "image_seo", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code, ShieldCheck, ListChecks, LayoutList, AlignLeft, Table, Target, PlusCircle } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeywords: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5,
    customOutline: ''
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to get default schedule date (24 hours from now)
  const getDefaultScheduleDate = () => {
    const date = new Date();
    date.setHours(date.getHours() + 24);
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const h = String(date.getHours()).padStart(2, '0');
    const min = String(date.getMinutes()).padStart(2, '0');
    return `${y}-${m}-${d}T${h}:${min}`;
  };

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
    setScheduleDate(getDefaultScheduleDate());
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeywords) {
      setError('দয়া করে টপিক এবং মেইন কিওয়ার্ডগুলো লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        mediaId = await uploadMedia(wpSettings, selectedImage, {
          title: article.image_seo.alt,
          alt_text: article.image_seo.alt,
          caption: article.image_seo.caption,
          description: `Representation of ${article.yoast_seo.focus_keyword}`
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      // Format schedule date: "YYYY-MM-DD HH:MM"
      let finalScheduleDate: string | undefined = undefined;
      if (isScheduling && scheduleDate) {
        finalScheduleDate = scheduleDate.replace('T', ' ');
      }

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: article.content,
        slug: article.slug,
        date: finalScheduleDate,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.yoast_seo.meta_desc,
        focusKeyword: article.yoast_seo.focus_keyword,
        seoTitle: article.yoast_seo.seo_title,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;

    const keyword = article.yoast_seo.focus_keyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;

    return { 
      wordCount, 
      density: density.toFixed(2), 
      seoTitleLength: article.yoast_seo.seo_title.length,
      metaDescLength: article.yoast_seo.meta_desc.length,
      hasTable: article.content.includes('<table'),
      hasTakeaways: article.content.includes('<blockquote') || article.content.includes('একনজরে')
    };
  }, [article]);

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-2 rounded-lg text-white shadow-lg">
                <Target size={24} />
              </div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-900 to-gray-600 hidden sm:block">Bangla Yoast Pro</h1>
            </div>
            <div className="flex gap-2 sm:gap-4">
              <button onClick={() => setActiveTab('generate')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'generate' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <FileText size={18} /> রাইটার
              </button>
              <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'settings' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3 text-red-700 animate-in fade-in slide-in-from-top-2">
            <AlertCircle size={20} className="shrink-0" />
            <p className="font-medium">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border-l-4 border-green-500 rounded-r-lg flex flex-col gap-2 text-green-700 animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} className="shrink-0" />
              <p className="font-bold text-lg">এসইও-অপ্টিমাইজড পাবলিশ সফল!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 font-semibold underline ml-8 hover:text-blue-800">পোস্টটি দেখুন →</a>
          </div>
        )}

        {activeTab === 'settings' ? (
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden max-w-2xl mx-auto">
            <div className="p-6 border-b border-gray-100 bg-gray-50/50">
              <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                <Settings className="text-blue-600" size={20} /> কনফিগারেশন
              </h2>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">ওয়ার্ডপ্রেস URL</label>
                <input type="url" placeholder="https://example.com" value={wpSettings.url} onChange={(e) => setWpSettings({...wpSettings, url: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">ইউজারনেম</label>
                  <input type="text" placeholder="admin" value={wpSettings.username} onChange={(e) => setWpSettings({...wpSettings, username: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">অ্যাপ্লিকেশন পাসওয়ার্ড</label>
                  <input type="password" placeholder="xxxx xxxx xxxx xxxx" value={wpSettings.appPassword} onChange={(e) => setWpSettings({...wpSettings, appPassword: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
              </div>
              <button onClick={saveSettings} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold hover:bg-blue-700 shadow-lg transition-all flex items-center justify-center gap-2">
                <Save size={20} /> সেটিংস সেভ করুন
              </button>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-md border border-gray-100">
                <h2 className="text-lg font-bold mb-6 text-gray-900 flex items-center gap-2">
                  <AlignLeft size={22} className="text-blue-600" /> এসইও ইনপুট
                </h2>
                <div className="space-y-5">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">আর্টিকেল টপিক</label>
                    <textarea rows={2} value={params.topic} onChange={(e) => setParams({...params, topic: e.target.value})} placeholder="যেমন: নতুন নিয়ম অনুযায়ী পাসপোর্ট রিন্যু" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none resize-none" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1"><PlusCircle size={14} className="text-blue-500"/> মেইন কিওয়ার্ডস (Multiple Main Keywords)</label>
                    <input type="text" value={params.primaryKeywords} onChange={(e) => setParams({...params, primaryKeywords: e.target.value})} placeholder="পাসপোর্ট রিন্যু, রিন্যু করার নিয়ম (কমা দিয়ে লিখুন)" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                    <p className="text-[10px] text-gray-500 mt-1">প্রথম কিওয়ার্ডটি প্রাইমারি হিসেবে ব্যবহার হবে।</p>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1"><PlusCircle size={14} className="text-indigo-400"/> সেকেন্ডারি কিওয়ার্ডস (Secondary Keywords)</label>
                    <input type="text" value={params.secondaryKeywords} onChange={(e) => setParams({...params, secondaryKeywords: e.target.value})} placeholder="আবেদন পদ্ধতি, প্রয়োজনীয় কাগজপত্র" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>

                  <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100 space-y-4">
                     <div>
                        <label className="block text-xs font-black text-blue-800 uppercase tracking-widest mb-2">Target Word Count</label>
                        <select value={params.wordCountRange} onChange={(e) => setParams({...params, wordCountRange: e.target.value})} className="w-full px-3 py-2.5 text-sm border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 bg-white font-medium">
                          <option>Short (800-1000 words)</option>
                          <option>Standard (1200-1500 words)</option>
                          <option>Long Form (2000-2500 words)</option>
                        </select>
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-blue-900 mb-2 flex items-center gap-2">
                           <LayoutList size={16} /> কাস্টম আউটলাইন (ঐচ্ছিক)
                        </label>
                        <textarea 
                           rows={3} 
                           value={params.customOutline} 
                           onChange={(e) => setParams({...params, customOutline: e.target.value})} 
                           placeholder="আপনার পছন্দমতো আউটলাইন দিন..." 
                           className="w-full px-4 py-3 border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm resize-y" 
                        />
                     </div>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1">
                      <FolderTree size={16} /> ক্যাটাগরি
                    </label>
                    <select value={selectedCategory} onChange={(e) => setSelectedCategory(Number(e.target.value))} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white">
                      <option value="">সিলেক্ট করুন...</option>
                      {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                    </select>
                  </div>

                  <button disabled={loading} onClick={handleGenerate} className="w-full bg-gradient-to-r from-blue-600 to-indigo-700 text-white py-4 rounded-xl font-bold hover:shadow-xl transition-all flex items-center justify-center gap-2 disabled:opacity-50">
                    {loading ? <Loader2 size={24} className="animate-spin" /> : <Target size={24} />} 
                    {loading ? 'জেনারেট হচ্ছে...' : 'আর্টিকেল জেনারেট করুন'}
                  </button>
                </div>
              </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
              {!article && !loading && (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-gray-400 bg-white border border-gray-100 rounded-3xl shadow-sm px-10">
                  <div className="bg-gray-50 p-6 rounded-full mb-6">
                    <Target size={64} className="opacity-10" />
                  </div>
                  <h3 className="text-xl font-bold text-gray-800 mb-2">আর্টিকেল প্রিভিউ</h3>
                  <p className="text-center max-w-sm">বামে কিওয়ার্ড দিয়ে শুরু করুন। AI আপনার জন্য অপ্টিমাইজড কন্টেন্ট তৈরি করবে।</p>
                </div>
              )}

              {loading && (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-blue-600 bg-white border border-gray-100 rounded-3xl shadow-sm px-10">
                  <Loader2 size={80} className="animate-spin opacity-20 mb-8" />
                  <h3 className="text-2xl font-black text-gray-900 mb-3 animate-pulse">কন্টেন্ট প্রসেসিং হচ্ছে...</h3>
                  <p className="text-gray-500 font-medium text-center">একাধিক কিওয়ার্ড অপ্টিমাইজ করে আর্টিকেল সাজানো হচ্ছে।</p>
                </div>
              )}

              {article && !loading && (
                <div className="space-y-6 animate-in slide-in-from-bottom-8 duration-700">
                  <div className="flex flex-wrap items-center justify-between gap-4 sticky top-[4.5rem] z-40 bg-white/80 backdrop-blur-xl p-5 rounded-3xl border border-gray-100 shadow-xl">
                    <div className="flex gap-3">
                      <button disabled={publishLoading} onClick={() => handlePublish(false)} className="bg-green-600 text-white px-8 py-3 rounded-2xl font-bold hover:bg-green-700 shadow-lg transition-all flex items-center gap-2 active:scale-95 disabled:opacity-50">
                        {publishLoading ? <Loader2 size={20} className="animate-spin" /> : <Send size={20} />} সরাসরি পাবলিশ
                      </button>
                      <button onClick={() => setShowScheduleModal(true)} className="bg-orange-500 text-white px-8 py-3 rounded-2xl font-bold hover:bg-orange-600 shadow-lg transition-all flex items-center gap-2 active:scale-95">
                        <Calendar size={20} /> শিডিউল
                      </button>
                    </div>
                    {stats && (
                      <div className="flex flex-wrap gap-3 items-center">
                        <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-black flex items-center gap-1"><BarChart3 size={14} /> {stats.wordCount} Words</div>
                        <div className="bg-purple-100 text-purple-700 px-3 py-1 rounded-full text-xs font-black flex items-center gap-1"><Target size={14} /> Density: {stats.density}%</div>
                      </div>
                    )}
                  </div>

                  <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-gray-50">
                    <div className="mb-10 pb-8 border-b border-gray-100">
                        <div className="flex items-center gap-2 mb-4 text-xs font-black text-green-600 uppercase tracking-widest"><ShieldCheck size={16} /> Yoast Optimized</div>
                        <h1 className="text-4xl font-black text-gray-900 mb-8 leading-tight">{article.title}</h1>

                        <div className="space-y-4">
                            <div className="bg-gray-50 p-4 rounded-2xl border border-gray-200">
                                <p className="text-[10px] font-black text-blue-600 uppercase mb-2">Snippet Preview</p>
                                <div className="space-y-1">
                                    <h3 className="text-[#1a0dab] text-xl font-medium hover:underline cursor-pointer">{article.yoast_seo.seo_title}</h3>
                                    <p className="text-[#006621] text-sm flex items-center gap-1">{article.slug}</p>
                                    <p className="text-[#4d5156] text-sm leading-relaxed">{article.yoast_seo.meta_desc}</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-8 text-gray-800 leading-relaxed preview-content prose prose-blue prose-lg max-w-none">
                       <div className="article-body-wrapper" dangerouslySetInnerHTML={{ __html: article.content }} />
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {showScheduleModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm transition-all">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full overflow-hidden border border-gray-100 animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
               <h3 className="text-2xl font-black text-gray-900">পোস্ট শিডিউল করুন</h3>
               <button onClick={() => setShowScheduleModal(false)} className="text-gray-400 hover:text-gray-900 text-3xl font-light">&times;</button>
            </div>
            <div className="p-8">
              <label className="block text-sm font-bold text-gray-700 mb-4 uppercase tracking-widest text-center">শিডিউল সময় (২৫ ঘণ্টা পর ডিফল্ট)</label>
              <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full px-5 py-4 border-2 border-gray-100 rounded-2xl mb-8 outline-none focus:border-blue-500 transition-all text-center text-lg font-bold" />
              <div className="flex gap-4">
                <button onClick={() => setShowScheduleModal(false)} className="flex-1 py-4 border rounded-2xl font-bold text-gray-500 hover:bg-gray-50">বাতিল</button>
                <button disabled={!scheduleDate || publishLoading} onClick={(e) => {
                  e.stopPropagation();
                  handlePublish(true);
                }} className="flex-1 py-4 bg-orange-500 text-white rounded-2xl font-black hover:shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2">
                  {publishLoading ? <Loader2 className="animate-spin" size={20} /> : <Calendar size={20} />} শিডিউল নিশ্চিত
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code, ShieldCheck, ListChecks, LayoutList, AlignLeft, Table, Target, PlusCircle } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeywords: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5,
    customOutline: ''
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  /**
   * Scheduling Instructions:
   * 1. Date Format: "YYYY-MM-DD HH:MM"
   * 2. Timing: 24 hours after {Current_Date}
   */
  const getDefaultScheduleDate = () => {
    const date = new Date();
    date.setHours(date.getHours() + 24);
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const h = String(date.getHours()).padStart(2, '0');
    const min = String(date.getMinutes()).padStart(2, '0');
    // Datetime-local input needs 'T' for presentation
    return `${y}-${m}-${d}T${h}:${min}`;
  };

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
    setScheduleDate(getDefaultScheduleDate());
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeywords) {
      setError('দয়া করে টপিক এবং মেইন কিওয়ার্ডগুলো লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        mediaId = await uploadMedia(wpSettings, selectedImage, {
          title: article.image_seo.alt,
          alt_text: article.image_seo.alt,
          caption: article.image_seo.caption,
          description: `Representation of ${article.yoast_seo.focus_keyword}`
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      // Format schedule date: strictly "YYYY-MM-DD HH:MM" per instructions
      let finalScheduleDate: string | undefined = undefined;
      if (isScheduling && scheduleDate) {
        finalScheduleDate = scheduleDate.replace('T', ' ');
      }

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: article.content,
        slug: article.slug,
        date: finalScheduleDate,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.yoast_seo.meta_desc,
        focusKeyword: article.yoast_seo.focus_keyword,
        seoTitle: article.yoast_seo.seo_title,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;

    const keyword = article.yoast_seo.focus_keyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;

    return { 
      wordCount, 
      density: density.toFixed(2), 
      seoTitleLength: article.yoast_seo.seo_title.length,
      metaDescLength: article.yoast_seo.meta_desc.length,
      hasTable: article.content.includes('<table'),
      hasTakeaways: article.content.includes('<blockquote') || article.content.includes('একনজরে')
    };
  }, [article]);

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-2 rounded-lg text-white shadow-lg">
                <Target size={24} />
              </div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-900 to-gray-600 hidden sm:block">Bangla Yoast Pro</h1>
            </div>
            <div className="flex gap-2 sm:gap-4">
              <button onClick={() => setActiveTab('generate')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'generate' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <FileText size={18} /> রাইটার
              </button>
              <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'settings' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3 text-red-700 animate-in fade-in slide-in-from-top-2">
            <AlertCircle size={20} className="shrink-0" />
            <p className="font-medium">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border-l-4 border-green-500 rounded-r-lg flex flex-col gap-2 text-green-700 animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} className="shrink-0" />
              <p className="font-bold text-lg">এসইও-অপ্টিমাইজড পাবলিশ সফল!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 font-semibold underline ml-8 hover:text-blue-800">পোস্টটি দেখুন →</a>
          </div>
        )}

        {activeTab === 'settings' ? (
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden max-w-2xl mx-auto">
            <div className="p-6 border-b border-gray-100 bg-gray-50/50">
              <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                <Settings className="text-blue-600" size={20} /> কনফিগারেশন
              </h2>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">ওয়ার্ডপ্রেস URL</label>
                <input type="url" placeholder="https://example.com" value={wpSettings.url} onChange={(e) => setWpSettings({...wpSettings, url: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">ইউজারনেম</label>
                  <input type="text" placeholder="admin" value={wpSettings.username} onChange={(e) => setWpSettings({...wpSettings, username: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">অ্যাপ্লিকেশন পাসওয়ার্ড</label>
                  <input type="password" placeholder="xxxx xxxx xxxx xxxx" value={wpSettings.appPassword} onChange={(e) => setWpSettings({...wpSettings, appPassword: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
              </div>
              <button onClick={saveSettings} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold hover:bg-blue-700 shadow-lg transition-all flex items-center justify-center gap-2">
                <Save size={20} /> সেটিংস সেভ করুন
              </button>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-md border border-gray-100">
                <h2 className="text-lg font-bold mb-6 text-gray-900 flex items-center gap-2">
                  <AlignLeft size={22} className="text-blue-600" /> এসইও ইনপুট
                </h2>
                <div className="space-y-5">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">আর্টিকেল টপিক</label>
                    <textarea rows={2} value={params.topic} onChange={(e) => setParams({...params, topic: e.target.value})} placeholder="যেমন: নতুন নিয়ম অনুযায়ী পাসপোর্ট রিন্যু" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none resize-none" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1"><PlusCircle size={14} className="text-blue-500"/> মেইন কিওয়ার্ডস (Multiple Main Keywords)</label>
                    <input type="text" value={params.primaryKeywords} onChange={(e) => setParams({...params, primaryKeywords: e.target.value})} placeholder="পাসপোর্ট রিন্যু, রিন্যু করার নিয়ম (কমা দিয়ে লিখুন)" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                    <p className="text-[10px] text-gray-500 mt-1">প্রথম কিওয়ার্ডটি প্রাইমারি হিসেবে ব্যবহার হবে।</p>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1"><PlusCircle size={14} className="text-indigo-400"/> সেকেন্ডারি কিওয়ার্ডস (Secondary Keywords)</label>
                    <input type="text" value={params.secondaryKeywords} onChange={(e) => setParams({...params, secondaryKeywords: e.target.value})} placeholder="আবেদন পদ্ধতি, প্রয়োজনীয় কাগজপত্র" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>

                  <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100 space-y-4">
                     <div>
                        <label className="block text-xs font-black text-blue-800 uppercase tracking-widest mb-2">Target Word Count</label>
                        <select value={params.wordCountRange} onChange={(e) => setParams({...params, wordCountRange: e.target.value})} className="w-full px-3 py-2.5 text-sm border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 bg-white font-medium">
                          <option>Short (800-1000 words)</option>
                          <option>Standard (1200-1500 words)</option>
                          <option>Long Form (2000-2500 words)</option>
                        </select>
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-blue-900 mb-2 flex items-center gap-2">
                           <LayoutList size={16} /> কাস্টম আউটলাইন (ঐচ্ছিক)
                        </label>
                        <textarea 
                           rows={3} 
                           value={params.customOutline} 
                           onChange={(e) => setParams({...params, customOutline: e.target.value})} 
                           placeholder="আপনার পছন্দমতো আউটলাইন দিন..." 
                           className="w-full px-4 py-3 border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm resize-y" 
                        />
                     </div>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1">
                      <FolderTree size={16} /> ক্যাটাগরি
                    </label>
                    <select value={selectedCategory} onChange={(e) => setSelectedCategory(Number(e.target.value))} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white">
                      <option value="">সিলেক্ট করুন...</option>
                      {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-1">
                      <ImageIcon size={16} /> ফিচারড ইমেজ
                    </label>
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                    <div onClick={() => fileInputRef.current?.click()} className="group cursor-pointer border-2 border-dashed border-gray-200 rounded-2xl p-2 text-center hover:border-blue-400 hover:bg-blue-50/50 transition-all">
                      {imagePreview ? (
                        <div className="relative">
                           <img src={imagePreview} alt="Preview" className="h-40 w-full object-cover rounded-xl shadow-inner" />
                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-bold rounded-xl transition-opacity text-xs text-center px-2">ছবি পরিবর্তন করুন</div>
                        </div>
                      ) : (
                        <div className="py-6 text-gray-400 flex flex-col items-center">
                          <ImageIcon size={32} className="mb-2 opacity-50" />
                          <span className="text-sm font-medium">এসইও ইমেজ আপলোড</span>
                        </div>
                      )}
                    </div>
                  </div>

                  <button disabled={loading} onClick={handleGenerate} className="w-full bg-gradient-to-r from-blue-600 to-indigo-700 text-white py-4 rounded-xl font-bold hover:shadow-xl transition-all flex items-center justify-center gap-2 disabled:opacity-50">
                    {loading ? <Loader2 size={24} className="animate-spin" /> : <Target size={24} />} 
                    {loading ? 'জেনারেট হচ্ছে...' : 'আর্টিকেল জেনারেট করুন'}
                  </button>
                </div>
              </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
              {!article && !loading && (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-gray-400 bg-white border border-gray-100 rounded-3xl shadow-sm px-10">
                  <div className="bg-gray-50 p-6 rounded-full mb-6">
                    <Target size={64} className="opacity-10" />
                  </div>
                  <h3 className="text-xl font-bold text-gray-800 mb-2">আর্টিকেল প্রিভিউ</h3>
                  <p className="text-center max-w-sm">বামে কিওয়ার্ড দিয়ে শুরু করুন। AI আপনার জন্য অপ্টিমাইজড কন্টেন্ট তৈরি করবে।</p>
                </div>
              )}

              {loading && (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-blue-600 bg-white border border-gray-100 rounded-3xl shadow-sm px-10">
                  <Loader2 size={80} className="animate-spin opacity-20 mb-8" />
                  <h3 className="text-2xl font-black text-gray-900 mb-3 animate-pulse">কন্টেন্ট প্রসেসিং হচ্ছে...</h3>
                  <p className="text-gray-500 font-medium text-center">একাধিক কিওয়ার্ড অপ্টিমাইজ করে আর্টিকেল সাজানো হচ্ছে।</p>
                </div>
              )}

              {article && !loading && (
                <div className="space-y-6 animate-in slide-in-from-bottom-8 duration-700">
                  <div className="flex flex-wrap items-center justify-between gap-4 sticky top-[4.5rem] z-40 bg-white/80 backdrop-blur-xl p-5 rounded-3xl border border-gray-100 shadow-xl">
                    <div className="flex gap-3">
                      <button disabled={publishLoading} onClick={() => handlePublish(false)} className="bg-green-600 text-white px-8 py-3 rounded-2xl font-bold hover:bg-green-700 shadow-lg transition-all flex items-center gap-2 active:scale-95 disabled:opacity-50">
                        {publishLoading ? <Loader2 size={20} className="animate-spin" /> : <Send size={20} />} সরাসরি পাবলিশ
                      </button>
                      <button onClick={() => setShowScheduleModal(true)} className="bg-orange-500 text-white px-8 py-3 rounded-2xl font-bold hover:bg-orange-600 shadow-lg transition-all flex items-center gap-2 active:scale-95">
                        <Calendar size={20} /> শিডিউল
                      </button>
                    </div>
                    {stats && (
                      <div className="flex flex-wrap gap-3 items-center">
                        <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-black flex items-center gap-1"><BarChart3 size={14} /> {stats.wordCount} Words</div>
                        <div className="bg-purple-100 text-purple-700 px-3 py-1 rounded-full text-xs font-black flex items-center gap-1"><Target size={14} /> Density: {stats.density}%</div>
                      </div>
                    )}
                  </div>

                  <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-gray-50">
                    <div className="mb-10 pb-8 border-b border-gray-100">
                        <div className="flex items-center gap-2 mb-4 text-xs font-black text-green-600 uppercase tracking-widest"><ShieldCheck size={16} /> Yoast Optimized</div>
                        <h1 className="text-4xl font-black text-gray-900 mb-8 leading-tight">{article.title}</h1>

                        <div className="space-y-4">
                            <div className="bg-gray-50 p-4 rounded-2xl border border-gray-200">
                                <p className="text-[10px] font-black text-blue-600 uppercase mb-2">Snippet Preview</p>
                                <div className="space-y-1">
                                    <h3 className="text-[#1a0dab] text-xl font-medium hover:underline cursor-pointer">{article.yoast_seo.seo_title}</h3>
                                    <p className="text-[#006621] text-sm flex items-center gap-1">{article.slug}</p>
                                    <p className="text-[#4d5156] text-sm leading-relaxed">{article.yoast_seo.meta_desc}</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-8 text-gray-800 leading-relaxed preview-content prose prose-blue prose-lg max-w-none">
                       <div className="article-body-wrapper" dangerouslySetInnerHTML={{ __html: article.content }} />
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {showScheduleModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm transition-all">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full overflow-hidden border border-gray-100 animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
               <h3 className="text-2xl font-black text-gray-900">পোস্ট শিডিউল করুন</h3>
               <button onClick={() => setShowScheduleModal(false)} className="text-gray-400 hover:text-gray-900 text-3xl font-light">&times;</button>
            </div>
            <div className="p-8">
              <label className="block text-sm font-bold text-gray-700 mb-4 uppercase tracking-widest text-center">শিডিউল সময় (২৫ ঘণ্টা পর ডিফল্ট)</label>
              <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full px-5 py-4 border-2 border-gray-100 rounded-2xl mb-8 outline-none focus:border-blue-500 transition-all text-center text-lg font-bold" />
              <div className="flex gap-4">
                <button onClick={() => setShowScheduleModal(false)} className="flex-1 py-4 border rounded-2xl font-bold text-gray-500 hover:bg-gray-50">বাতিল</button>
                <button disabled={!scheduleDate || publishLoading} onClick={(e) => {
                  e.stopPropagation();
                  handlePublish(true);
                }} className="flex-1 py-4 bg-orange-500 text-white rounded-2xl font-black hover:shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2">
                  {publishLoading ? <Loader2 className="animate-spin" size={20} /> : <Calendar size={20} />} শিডিউল নিশ্চিত
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Settings, FileText, Send, Calendar, CheckCircle, AlertCircle, Loader2, Save, ImageIcon, FolderTree, BarChart3, Type as TypeIcon, Globe, Code, ShieldCheck, ListChecks, LayoutList, AlignLeft, Table, Target, PlusCircle } from 'lucide-react';
import { GenerationParams, GeneratedArticle, WPSettings, WPCategory } from './types';
import { generateSEOArticle } from './services/geminiService';
import { publishToWP, fetchCategories, uploadMedia, ensureTags } from './services/wordpressService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'settings'>('generate');
  const [params, setParams] = useState<GenerationParams>({
    topic: '',
    primaryKeywords: '',
    secondaryKeywords: '',
    targetAudience: '',
    wordCountRange: 'Standard Blog (1200-1500 words)',
    keywordDensity: 1.5,
    customOutline: ''
  });
  const [wpSettings, setWpSettings] = useState<WPSettings>({
    url: '',
    username: '',
    appPassword: ''
  });
  const [categories, setCategories] = useState<WPCategory[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | undefined>();
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [article, setArticle] = useState<GeneratedArticle | null>(null);
  const [loading, setLoading] = useState(false);
  const [publishLoading, setPublishLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ link: string } | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  /**
   * Updated Scheduling Instructions:
   * 1. Date Format: Strictly "YYYY-MM-DDTHH:MM:SS" (e.g. 2025-12-29T14:00:00)
   * 2. Timing: Set to 24 hours after current time.
   */
  const getDefaultScheduleDate = () => {
    const date = new Date();
    date.setHours(date.getHours() + 24);
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const h = String(date.getHours()).padStart(2, '0');
    const min = String(date.getMinutes()).padStart(2, '0');
    // Datetime-local input format: YYYY-MM-DDTHH:MM
    return `${y}-${m}-${d}T${h}:${min}`;
  };

  useEffect(() => {
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    }
    setScheduleDate(getDefaultScheduleDate());
  }, []);

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeywords) {
      setError('দয়া করে টপিক এবং মেইন কিওয়ার্ডগুলো লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। আবার চেষ্টা করুন।');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        mediaId = await uploadMedia(wpSettings, selectedImage, {
          title: article.image_seo.alt,
          alt_text: article.image_seo.alt,
          caption: article.image_seo.caption,
          description: `Representation of ${article.yoast_seo.focus_keyword}`
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      /**
       * Strict Formatting: Output strictly in 'YYYY-MM-DDTHH:MM:SS' format.
       * datetime-local returns 'YYYY-MM-DDTHH:MM'. We append ':00' for seconds.
       */
      let finalScheduleDate: string | undefined = undefined;
      if (isScheduling && scheduleDate) {
        finalScheduleDate = `${scheduleDate}:00`;
      }

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: article.content,
        slug: article.slug,
        date: finalScheduleDate,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.yoast_seo.meta_desc,
        focusKeyword: article.yoast_seo.focus_keyword,
        seoTitle: article.yoast_seo.seo_title,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;

    const keyword = article.yoast_seo.focus_keyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;

    return { 
      wordCount, 
      density: density.toFixed(2), 
      seoTitleLength: article.yoast_seo.seo_title.length,
      metaDescLength: article.yoast_seo.meta_desc.length,
      hasTable: article.content.includes('<table'),
      hasTakeaways: article.content.includes('<blockquote') || article.content.includes('একনজরে')
    };
  }, [article]);

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-2 rounded-lg text-white shadow-lg">
                <Target size={24} />
              </div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-900 to-gray-600 hidden sm:block">Bangla Yoast Pro</h1>
            </div>
            <div className="flex gap-2 sm:gap-4">
              <button onClick={() => setActiveTab('generate')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'generate' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <FileText size={18} /> রাইটার
              </button>
              <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'settings' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3 text-red-700 animate-in fade-in slide-in-from-top-2">
            <AlertCircle size={20} className="shrink-0" />
            <p className="font-medium">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border-l-4 border-green-500 rounded-r-lg flex flex-col gap-2 text-green-700 animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center gap-3">
              <CheckCircle size={20} className="shrink-0" />
              <p className="font-bold text-lg">এসইও-অপ্টিমাইজড পাবলিশ সফল!</p>
            </div>
            <a href={success.link} target="_blank" rel="noreferrer" className="text-blue-600 font-semibold underline ml-8 hover:text-blue-800">পোস্টটি দেখুন →</a>
          </div>
        )}

        {activeTab === 'settings' ? (
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden max-w-2xl mx-auto">
            <div className="p-6 border-b border-gray-100 bg-gray-50/50">
              <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                <Settings className="text-blue-600" size={20} /> কনফিগারেশন
              </h2>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">ওয়ার্ডপ্রেস URL</label>
                <input type="url" placeholder="https://example.com" value={wpSettings.url} onChange={(e) => setWpSettings({...wpSettings, url: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">ইউজারনেম</label>
                  <input type="text" placeholder="admin" value={wpSettings.username} onChange={(e) => setWpSettings({...wpSettings, username: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">অ্যাপ্লিকেশন পাসওয়ার্ড</label>
