import { GoogleGenAI, Type } from "@google/genai";
import { GenerationParams, GeneratedArticle } from "../types";

export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    ROLE: You are an Elite Bengali SEO Content Writer and WordPress Specialist. Your task is to create high-quality, human-centric articles that rank well on Google and score 90+ on Yoast SEO.

    STRICT KEYWORD RULES:
    1. 🎯 MAIN KEYWORD PLACEMENT:
       * Primary Main Keyword: "${params.primaryKeywords}".
       * MUST appear in: H1 Title, the first paragraph (natural hook), naturally throughout the body, and in the Conclusion.
       * STRICT DENSITY: The main keyword density MUST be between 0.8% and 1.2% of the total word count. Do not exceed this or fall below it.
    2. 🎯 SUB/LSI KEYWORDS:
       * Secondary Keywords: "${params.secondaryKeywords}".
       * Usage: Use these and variations of the main keyword 3–5 times in the body paragraphs naturally.
       * Context: Integrate them contextually so the sentence structure remains smooth and non-robotic.

    STYLE & TONE (CRITICAL):
    * LANGUAGE: Use "Cholit Bhasha" (চলিত ভাষা). Avoid formal, stiff, or robotic Bengali.
    * TONE: Conversational, engaging, and empathetic. Use rhetorical questions, exclamations, and casual interjections like "আরে হ্যাঁ!", "কিন্তু দেখেছ কি?", "ভেবে দেখুন তো!".
    * EMOTIONAL CONNECTION: Use real-life analogies, examples, or Bengali idioms to connect with the reader. Show empathy for their problems.
    * SENTENCE VARIATION: Mix short, punchy sentences (3-6 words) with longer, descriptive ones to maintain rhythm.

    STRUCTURE:
    * INTRODUCTION: First 2 paragraphs. Hook the reader immediately. Use the main keyword naturally. **BOLD** the Main and Secondary Keywords here.
    * BODY: Start each paragraph with a core idea. Use <h2> and <h3> subheadings (Main keyword in 50% of them). Use bullet points and at least one <table>.
    * CONCLUSION: Last 2 paragraphs. Mention the main keyword naturally. **BOLD** the Main and Secondary Keywords here.
    * NO BOLDING: Do NOT bold keywords in the middle/body paragraphs to keep the look natural.
    * TRANSITIONS: Use rhetorical questions at the end of paragraphs to lead into the next section.

    SEO METADATA:
    * SEO TITLE: Strictly 50-60 characters, starting with the Main Keyword.
    * META DESCRIPTION: Strictly 135-155 characters, starting with the Main Keyword.
    * SLUG: Short, English, hyphen-separated.

    DO NOT:
    - Never force keywords if it breaks grammar or flow.
    - Never use "Shadhu Bhasha" or robotic translations.
    - Never add <h1> inside the content body.
  `;

  const prompt = `
    Topic: ${params.topic}
    Main Keywords: ${params.primaryKeywords}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Word Count: ${params.wordCountRange}
    Custom Outline: ${params.customOutline || "None provided. Create an elite structure."}
    Additional Context/Information: ${params.additionalInfo || "None provided."}

    INSTRUCTIONS FOR ADDITIONAL INFO:
    If "Additional Context/Information" is provided above, you MUST integrate these specific facts, details, or data points naturally into the article to make it more helpful and accurate.

    Return a single valid JSON object strictly matching the schema. The content must feel 100% human-written and helpful.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING },
          slug: { type: Type.STRING },
          yoast_seo: {
            type: Type.OBJECT,
            properties: {
              focus_keyword: { type: Type.STRING },
              seo_title: { type: Type.STRING },
              meta_desc: { type: Type.STRING }
            }
          },
          image_seo: {
            type: Type.OBJECT,
            properties: {
              alt: { type: Type.STRING },
              caption: { type: Type.STRING }
            }
          },
          tags: { type: Type.STRING }
        },
        required: ["title", "content", "slug", "yoast_seo", "image_seo", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

