    // Note: link1 increased the array length by 1
    if (posts.length > 1) {
      const link2Html = `<p><strong>আরও পড়ুন: <a href="${posts[1].link}" rel="dofollow">${posts[1].title}</a></strong></p>`;
      newContentParts.splice(newContentParts.length - 1, 0, link2Html);
    }

    return newContentParts.join('</p>') + '</p>';
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }

    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        let imageToUpload = selectedImage;
        try {
           if (selectedImage.type.startsWith('image/')) {
               imageToUpload = await convertToWebP(selectedImage);
           }
        } catch (convErr) {
           console.error("WebP conversion failed", convErr);
        }
        const focusKeyword = article.yoast_seo.focus_keyword;
        mediaId = await uploadMedia(wpSettings, imageToUpload, {
          title: focusKeyword,
          alt_text: focusKeyword,
