  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('wp_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWpSettings(parsed);
      loadCategories(parsed);
    } else {
      loadCategories(DEFAULT_WP_SETTINGS);
    }
    setScheduleDate(getDefaultScheduleDate());
  }, []);

  const checkApiKey = async () => {
    try {
      const selected = await window.aistudio.hasSelectedApiKey();
      setHasKey(selected);
    } catch (e) {
      setHasKey(false);
    }
  };

  const handleOpenSelectKey = async () => {
    await window.aistudio.openSelectKey();
    setHasKey(true); // Assume success per instructions
  };

  const getDefaultScheduleDate = () => {
    const date = new Date();
    date.setHours(date.getHours() + 24);
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const h = String(date.getHours()).padStart(2, '0');
    const min = String(date.getMinutes()).padStart(2, '0');
    return `${y}-${m}-${d}T${h}:${min}`;
  };

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
