    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      const errMsg = err.message || '';
      if (errMsg.toLowerCase().includes('permission denied') || errMsg.toLowerCase().includes('not found')) {
        setError('Gemini API Permission Denied. Please ensure you have selected a valid API key from a paid project.');
