        setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। ' + errMsg);
      }
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const injectInternalLinks = (content: string, posts: {title: string, link: string}[]) => {
    if (posts.length === 0) return content;
    const paragraphs = content.split('</p>');
    const filteredParagraphs = paragraphs.filter(p => p.trim() !== '');
    if (filteredParagraphs.length < 3) return content;
    let newContentParts = [...filteredParagraphs];
    const link1Html = `<p><strong>আরও পড়ুন: <a href="${posts[0].link}" rel="dofollow">${posts[0].title}</a></strong></p>`;
    newContentParts.splice(2, 0, link1Html);
    if (posts.length > 1) {
      const link2Html = `<p><strong>আরও পড়ুন: <a href="${posts[1].link}" rel="dofollow">${posts[1].title}</a></strong></p>`;
      newContentParts.splice(newContentParts.length - 1, 0, link2Html);
    }
    return newContentParts.join('</p>') + '</p>';
  };

  const handlePublish = async (isScheduling = false) => {
