    const min = String(date.getMinutes()).padStart(2, '0');
    return `${y}-${m}-${d}T${h}:${min}`;
  };

  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeywords) {
      setError(params.language === 'bn' ? 'দয়া করে টপিক এবং মেইন কিওয়ার্ডগুলো লিখুন।' : 'Please enter article topic and primary keywords.');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      const errMsg = err.message || '';
      if (errMsg.toLowerCase().includes('permission denied') || errMsg.toLowerCase().includes('not found')) {
        setError('Gemini API Permission Denied. Please ensure you have selected a valid API key from a paid project.');
        setHasKey(false); // Trigger re-selection UI
      } else {
        setError(params.language === 'bn' ? 'আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। ' + errMsg : 'Article generation failed. ' + errMsg);
      }
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const injectInternalLinks = (content: string, posts: {title: string, link: string}[]) => {
    if (posts.length === 0) return content;
    const paragraphs = content.split('</p>');
    const filteredParagraphs = paragraphs.filter(p => p.trim() !== '');
    if (filteredParagraphs.length < 3) return content;
    let newContentParts = [...filteredParagraphs];
    const prefix = params.language === 'bn' ? 'আরও পড়ুন' : 'Read More';
    const link1Html = `<p><strong>${prefix}: <a href="${posts[0].link}" rel="dofollow">${posts[0].title}</a></strong></p>`;
    newContentParts.splice(2, 0, link1Html);
    if (posts.length > 1) {
      const link2Html = `<p><strong>${prefix}: <a href="${posts[1].link}" rel="dofollow">${posts[1].title}</a></strong></p>`;
      newContentParts.splice(newContentParts.length - 1, 0, link2Html);
    }
    return newContentParts.join('</p>') + '</p>';
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError(params.language === 'bn' ? 'দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।' : 'Please check your WordPress settings.');
      return;
    }
    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        let imageToUpload = selectedImage;
        try {
           if (selectedImage.type.startsWith('image/')) {
               imageToUpload = await convertToWebP(selectedImage);
           }
        } catch (convErr) {
           console.error("WebP conversion failed", convErr);
        }
        const focusKeyword = article.yoast_seo.focus_keyword;
        mediaId = await uploadMedia(wpSettings, imageToUpload, {
          title: focusKeyword,
          alt_text: focusKeyword,
          caption: focusKeyword,
          description: focusKeyword
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      let finalScheduleDate: string | undefined = undefined;
      if (isScheduling && scheduleDate) {
        finalScheduleDate = `${scheduleDate}:00`;
      }

      let contentWithLinks = article.content;
      if (selectedCategory) {
        try {
          const recentPosts = await fetchRecentPostsByCategory(wpSettings, selectedCategory, 2);
          contentWithLinks = injectInternalLinks(article.content, recentPosts);
        } catch (linkErr) {
          console.error("Internal linking fetch failed", linkErr);
        }
      }

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: contentWithLinks,
        slug: article.slug,
        date: finalScheduleDate,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.yoast_seo.meta_desc,
        focusKeyword: article.yoast_seo.focus_keyword,
        seoTitle: article.yoast_seo.seo_title,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const keyword = article.yoast_seo.focus_keyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;
    return { 
      wordCount, density: density.toFixed(2), 
      seoTitleLength: article.yoast_seo.seo_title.length,
      metaDescLength: article.yoast_seo.meta_desc.length,
      hasTable: article.content.includes('<table'),
      hasTakeaways: article.content.includes('<blockquote') || article.content.includes('একনজরে')
    };
  }, [article]);

  if (hasKey === false) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-gray-100 max-w-md w-full space-y-8 animate-in fade-in zoom-in-95">
          <div className="bg-blue-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto text-blue-600">
            <Key size={40} />
          </div>
          <div className="space-y-4">
            <h1 className="text-3xl font-black text-gray-900">API Key Required</h1>
            <p className="text-gray-600 leading-relaxed">
              Gemini 3 models and advanced SEO tasks require an API key from a <strong>paid Google Cloud project</strong>.
            </p>
            <a 
              href="https://ai.google.dev/gemini-api/docs/billing" 
              target="_blank" 
              rel="noreferrer" 
              className="inline-flex items-center gap-2 text-blue-600 font-bold hover:underline"
            >
              Billing Documentation <ExternalLink size={16} />
            </a>
          </div>
          <button 
            onClick={handleOpenSelectKey}
            className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg hover:bg-blue-700 shadow-xl transition-all active:scale-95"
          >
            Select API Key
          </button>
        </div>
      </div>
    );
  }

  if (hasKey === null) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="animate-spin text-blue-600" size={48} />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-2 rounded-lg text-white shadow-lg">
                <Target size={24} />
              </div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-900 to-gray-600 hidden sm:block">Bangla Yoast Pro</h1>
            </div>
            <div className="flex gap-2 sm:gap-4">
              <button onClick={() => setActiveTab('generate')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'generate' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <FileText size={18} /> রাইটার
              </button>
              <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all ${activeTab === 'settings' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}>
                <Settings size={18} /> সেটিংস
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
