export const generateSEOArticle = async (params: GenerationParams): Promise<GeneratedArticle> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Bengali Generation Only
  const systemInstructionBn = `
    ROLE: You are an Elite Bengali SEO Content Writer and WordPress Specialist. Your task is to create high-quality, human-centric articles that rank well on Google and score 90+ on Yoast SEO.

    STRICT KEYWORD RULES:
    1. 🎯 MAIN KEYWORD PLACEMENT:
       * Primary Main Keyword: "${params.primaryKeywords}".
       * MUST appear in: H1 Title, the first paragraph (natural hook), naturally throughout the body, and in the Conclusion.
       * STRICT DENSITY: 0.8% to 1.2%.
    2. 🎯 SUB/LSI KEYWORDS: "${params.secondaryKeywords}". Use 3–5 times.

    STYLE & TONE (CRITICAL):
    * LANGUAGE: "Cholit Bhasha" (চলিত ভাষা). Avoid formal Bengali.
    * TONE: Conversational and empathetic. Use "আরে হ্যাঁ!", "ভেবে দেখুন তো!".

    STRUCTURE:
    * INTRODUCTION: First 2 paragraphs. **BOLD** Main/Secondary keywords here.
    * BODY: <h2> and <h3> subheadings. Bullet points and at least one <table>.
    * CONCLUSION: Last 2 paragraphs. **BOLD** Main/Secondary keywords here.
    * NO BOLDING in middle paragraphs.

    SEO METADATA:
    * SEO TITLE: 50-60 chars.
    * META DESCRIPTION: 135-155 chars.
    * SLUG: English, hyphenated.
  `;

  const promptBn = `
    Topic: ${params.topic}
    Main Keywords: ${params.primaryKeywords}
    Secondary Keywords: ${params.secondaryKeywords}
    Target Word Count: ${params.wordCountRange}
    Custom Outline: ${params.customOutline || "None provided."}
    Additional Info: ${params.additionalInfo || "None provided."}

    Return a single valid JSON object strictly matching the schema.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: promptBn,
    config: {
      systemInstruction: systemInstructionBn,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING },
          slug: { type: Type.STRING },
          yoast_seo: {
            type: Type.OBJECT,
            properties: {
              focus_keyword: { type: Type.STRING },
              seo_title: { type: Type.STRING },
              meta_desc: { type: Type.STRING }
            }
          },
          image_seo: {
            type: Type.OBJECT,
            properties: {
              alt: { type: Type.STRING },
              caption: { type: Type.STRING }
            }
          },
          tags: { type: Type.STRING }
        },
        required: ["title", "content", "slug", "yoast_seo", "image_seo", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

