  const loadCategories = async (settings: WPSettings) => {
    if (!settings.url || !settings.appPassword) return;
    try {
      const cats = await fetchCategories(settings);
      setCategories(cats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('wp_settings', JSON.stringify(wpSettings));
    loadCategories(wpSettings);
    alert('সেটিংস সেভ করা হয়েছে!');
    setActiveTab('generate');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!params.topic || !params.primaryKeywords) {
      setError('দয়া করে টপিক এবং মেইন কিওয়ার্ডগুলো লিখুন।');
      return;
    }
    setLoading(true);
    setError(null);
    setArticle(null);
    setSuccess(null);
    try {
      const result = await generateSEOArticle(params);
      setArticle(result);
    } catch (err: any) {
      setError('আর্টিকেল জেনারেট করতে সমস্যা হয়েছে। ' + (err.message || ''));
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const injectInternalLinks = (content: string, posts: {title: string, link: string}[]) => {
    if (posts.length === 0) return content;
    const paragraphs = content.split('</p>');
    const filteredParagraphs = paragraphs.filter(p => p.trim() !== '');
    if (filteredParagraphs.length < 3) return content;
    let newContentParts = [...filteredParagraphs];
    const prefix = 'আরও পড়ুন';
    const link1Html = `<p><strong>${prefix}: <a href="${posts[0].link}" rel="dofollow">${posts[0].title}</a></strong></p>`;
    newContentParts.splice(2, 0, link1Html);
    if (posts.length > 1) {
      const link2Html = `<p><strong>${prefix}: <a href="${posts[1].link}" rel="dofollow">${posts[1].title}</a></strong></p>`;
      newContentParts.splice(newContentParts.length - 1, 0, link2Html);
    }
    return newContentParts.join('</p>') + '</p>';
  };

  const handlePublish = async (isScheduling = false) => {
    if (!article || !wpSettings.url || !wpSettings.username || !wpSettings.appPassword) {
      setError('দয়া করে ওয়ার্ডপ্রেস সেটিংস ঠিক করুন।');
      return;
    }
    setPublishLoading(true);
    setError(null);
    try {
      let mediaId: number | undefined;
      if (selectedImage) {
        let imageToUpload = selectedImage;
        try {
           if (selectedImage.type.startsWith('image/')) {
               imageToUpload = await convertToWebP(selectedImage);
           }
        } catch (convErr) {
           console.error("WebP conversion failed", convErr);
        }

        // Use primary keywords as the main keyword for image metadata
        const mainKeyword = params.primaryKeywords;

        mediaId = await uploadMedia(wpSettings, imageToUpload, {
          title: mainKeyword,
          alt_text: mainKeyword,
          caption: mainKeyword,
          description: mainKeyword
        });
      }

      let tagIds: number[] = [];
      if (article.tags) {
        const tagList = article.tags.split(',').map(t => t.trim());
        tagIds = await ensureTags(wpSettings, tagList);
      }

      let finalScheduleDate: string | undefined = undefined;
      if (isScheduling && scheduleDate) {
        finalScheduleDate = `${scheduleDate}:00`;
      }

      let contentWithLinks = article.content;
      if (selectedCategory) {
        try {
          const recentPosts = await fetchRecentPostsByCategory(wpSettings, selectedCategory, 2);
          contentWithLinks = injectInternalLinks(article.content, recentPosts);
        } catch (linkErr) {
          console.error("Internal linking fetch failed", linkErr);
        }
      }

      const result = await publishToWP(wpSettings, {
        title: article.title,
        content: contentWithLinks,
        slug: article.slug,
        date: finalScheduleDate,
        category: selectedCategory,
        tags: tagIds,
        metaDescription: article.yoast_seo.meta_desc,
        focusKeyword: article.yoast_seo.focus_keyword,
        seoTitle: article.yoast_seo.seo_title,
        featuredMediaId: mediaId
      });
      setSuccess({ link: result.link });
      setShowScheduleModal(false);
    } catch (err: any) {
      setError(err.message || 'ওয়ার্ডপ্রেসে পাবলিশ করতে সমস্যা হয়েছে।');
    } finally {
      setPublishLoading(false);
    }
  };

  const stats = useMemo(() => {
    if (!article) return null;
    const text = (article.title + ' ' + article.content).replace(/<[^>]*>/g, ' ');
    const words = text.trim().split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const keyword = article.yoast_seo.focus_keyword.toLowerCase();
    const regex = new RegExp(keyword, 'gi');
    const matches = text.toLowerCase().match(regex);
    const keywordCount = matches ? matches.length : 0;
    const density = wordCount > 0 ? (keywordCount / wordCount) * 100 : 0;
    return { 
      wordCount, density: density.toFixed(2), 
      seoTitleLength: article.yoast_seo.seo_title.length,
      metaDescLength: article.yoast_seo.meta_desc.length,
      hasTable: article.content.includes('<table'),
      hasTakeaways: article.content.includes('<blockquote') || article.content.includes('একনজরে')
    };
  }, [article]);

