                    <input type="text" value={params.secondaryKeywords} onChange={(e) => setParams({...params, secondaryKeywords: e.target.value})} placeholder="আবেদন পদ্ধতি, কাগজপত্র" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" />
