                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-bold rounded-xl transition-opacity text-xs text-center px-2">ছবি পরিবর্তন করুন</div>
                        </div>
